export const longDescriptions: Record<string, Record<string, string>> = {
  "work-hours-tracker": {
    en: "Work Hours Tracker is a free iOS timesheet app designed for hourly workers, freelancers, shift schedulers, and anyone who needs an accurate record of the hours they have worked and the pay they have earned. The app replaces the paper notebook or the messy spreadsheet at the bottom of the drawer. Tap once when you clock in, tap again when you clock out, and the rest happens automatically: minutes are calculated, breaks are subtracted, overtime is applied, and a running total of what you are owed stays up to date. Built-in labor-law presets for thirteen countries and regions turn statutory rules on night work, weekly caps and overtime rates into a one-tap setup; custom rules cover everything else. The app tracks multiple jobs in parallel, so a barista with a weekday café shift and a weekend market gig sees both ledgers in one place. Every record can be exported as a CSV or PDF timesheet, which makes it easy to share with a payroll clerk or to keep as your own backup. The whole app is offline by default — your work hours are stored on your phone, never uploaded, and the interface is available in fourteen languages. A one-time or annual subscription unlocks unlimited jobs and removes ads; the core tracker stays free.",
    zh: "Work Hours Tracker 是一款免费的 iOS 工时记录 App，专为时薪工作者、自由职业者、轮班族，以及所有需要精确记录工时与收入的人打造，让你彻底告别抽屉里那本旧笔记本和乱成一团的表格。上班时轻点一下打卡，下班时再轻点一下，剩下的事全部自动完成：分钟数精准累计、休息时间自动扣除、加班费自动套用，你该拿多少钱也会实时更新。App 内置 13 个国家和地区的劳动法预设方案，把夜班规则、每周工时上限、加班费率这些法定条款变成一键即可完成的设置；其他情况也能通过自定义规则灵活覆盖。你还可以同时记录多份工作，比如工作日在咖啡馆做咖啡师、周末去市集摆摊，两本账都能在同一个界面里看得清清楚楚。每一条记录都能导出成 CSV 或 PDF 工时表，方便交给发工资的同事，也方便自己留存备份。整个 App 默认离线运行，工时数据只保存在你的手机上，绝不上传，界面支持 14 种语言。买断或年度订阅可解锁无限工作数量并去除广告；核心的打卡记录功能永久免费。",
    "zh-TW": "Work Hours Tracker 是一款專為時薪工作者、自由接案者、輪班排程者,以及需要精確記錄工時與薪資的使用者所打造的免費 iOS 工時表 App,讓你告別抽屜裡那本舊筆記本或亂七八糟的試算表。上班打卡輕點一次,下班再輕點一次,接下來的事 App 自動搞定:分鐘數精準計算、休息時間自動扣除、加班費自動套用,你應得的累計薪資隨時保持最新。內建 13 個國家與地區的勞工法預設,涵蓋夜間工作、每週工時上限與加班費率等法定規範,一鍵即可套用;其他自訂規則也能完整設定。App 可同時追蹤多份工作,像是平日在咖啡廳、週末到市集擺攤的服務生,所有帳目都能集中查看。每一筆紀錄都能匯出成 CSV 或 PDF 工時表,方便交給薪資管理人員,或是你自己留存備份。整個 App 預設為離線運作,工時資料只儲存在你的手機上,絕不上傳,介面支援 14 種語言。一次性或年度訂閱可解鎖無限工作數並去除廣告;核心的打卡功能則永久免費。",
    ja: "Work Hours Trackerは、時給で働く方、フリーランス、シフト勤務の管理担当者など、自分の労働時間と稼いだ賃金を正確に記録したいすべての人のための、無料iOSタイムシートアプリです。引き出しの奥に眠る紙のノートや、散らかったスプレッドシートはもう必要ありません。出勤時に1回タップ、退勤時に再度タップするだけで、後はすべて自動で行われます。分単位の計算、休憩時間の控除、残業代の適用、そしてあなたに支払われるべき金額の最新合計が常に表示されます。13の国と地域に対応した労働法制プリセットを備えているため、夜間労働や週間上限、残業代の法定ルールもワンタップで設定できます。その他のルールはカスタム設定で対応可能です。複数の仕事を並行して管理できるので、平日のカフェでのシフトと週末のマーケットでの仕事を掛け持ちしている方も、両方の台帳を一か所で確認できます。すべての記録はCSVまたはPDF形式のタイムシートとしてエクスポートできるため、給与担当者に共有するのも、自分用のバックアップとして保管するのも簡単です。アプリ本体はオフラインで動作し、労働時間データはスマートフォン内に保存されてアップロードされることはありません。インターフェースは14言語に対応しています。サブスクリプション（買い切りまたは年額）を契約すると、ジョブ数の上限が解除され広告も非表示になりますが、基本機能は無料でご利用いただけます。",
    ko: "Work Hours Tracker는 시급 근로자와 프리랜서, 교대 근무자를 위한 무료 iOS 근태 앱입니다. 종이 수첩과 어수선한 스프레드시트는 이제 안녕이죠. 출근할 때 한 번 탭, 퇴근할 때 한 번 탭하면 나머지는 자동으로 처리됩니다. 분 단위 계산, 휴식 시간 차감, 연장근무 적용까지 알아서 진행되고, 받을 금액도 실시간으로 쌓여 갑니다. 13개국 노동법 기본 설정으로 야간 근무, 주간 한도, 연장근무 수당을 탭 한 번에 적용할 수 있고, 그 외 규칙은 직접 맞춤 설정이 가능합니다. 평일 카페와 주말 마켓, 여러 근무지의 기록을 한 화면에서 한눈에 확인하세요. 모든 기록은 CSV 또는 PDF 타임시트로 내보낼 수 있어 급여 담당자에게 공유하거나 개인 백업용으로 간편합니다. 앱은 기본적으로 오프라인 작동하며 근무 시간은 폰에만 저장됩니다. 인터페이스는 14개 언어로 제공되고, 일회성 또는 연간 구독으로 무제한 근무지와 광고 제거가 가능합니다. 핵심 근태 추적 기능은 무료로 계속 이용하실 수 있습니다.",
    vi: "Work Hours Tracker là ứng dụng chấm công miễn phí trên iOS, được thiết kế dành cho người làm theo giờ, freelancer, người quản lý ca làm và bất kỳ ai cần theo dõi chính xác số giờ đã làm cùng số tiền đã kiếm được. Ứng dụng thay thế hoàn toàn cho cuốn sổ tay giấy hay những bảng tính lộn xộn nằm sâu trong ngăn kéo. Bạn chỉ cần chạm một lần khi bắt đầu ca, chạm thêm lần nữa khi kết thúc, phần còn lại sẽ tự động diễn ra: phút làm việc được tính toán, giờ giải lao được trừ ra, làm thêm được áp dụng, và tổng số tiền bạn được nhận luôn được cập nhật liên tục. Các cài đặt sẵn về luật lao động cho 13 quốc gia và vùng lãnh thổ biến những quy định pháp luật về làm đêm, giới hạn tuần và mức làm thêm thành một bước thiết lập đơn giản; những quy tắc tùy chỉnh sẽ lo phần còn lại. Ứng dụng theo dõi nhiều công việc song song, nên một bạn barista vừa làm ca quán cà phê ngày thường vừa đi làm thêm chợ cuối tuần đều có thể thấy cả hai sổ công trong cùng một nơi. Mỗi bản ghi đều có thể xuất ra CSV hoặc bảng chấm công PDF để dễ dàng chia sẻ với nhân viên lương bổng hoặc giữ làm bản sao lưu cho riêng bạn. Toàn bộ ứng dụng hoạt động ngoại tuyến theo mặc định — giờ làm của bạn được lưu ngay trên điện thoại, không bao giờ tải lên đám mây, và giao diện có sẵn bằng 14 ngôn ngữ. Một gói đăng ký một lần hoặc hằng năm sẽ mở khóa số lượng công việc không giới hạn và xóa quảng cáo; phần chấm công cốt lõi vẫn luôn miễn phí.",
    id: "Work Hours Tracker adalah aplikasi absensi iOS gratis yang dirancang khusus untuk pekerja lepas, pekerja shift, freelancer, serta siapa pun yang butuh catatan akurat tentang jam kerja yang sudah mereka selesaikan dan gaji yang sudah mereka dapatkan dari pekerjaan tersebut. Aplikasi ini pada dasarnya menggantikan buku catatan kertas atau spreadsheet berantakan yang biasa tersimpan di laci dan jarang disentuh lagi. Cukup ketuk sekali saat mulai kerja, ketuk lagi saat pulang, dan semua sisanya terjadi secara otomatis: menit dihitung dengan tepat, waktu istirahat dikurangi sesuai aturan, lembur diterapkan otomatis, dan total berjalan dari apa yang seharusnya kamu terima selalu diperbarui di layar. Fitur preset hukum ketenagakerjaan bawaan untuk tiga belas negara dan kawasan akan mengubah aturan resmi tentang kerja malam, batas jam mingguan, dan tarif lembur menjadi pengaturan sekali ketuk yang praktis; kalau pekerjaanmu punya aturan sendiri yang berbeda, aturan kustom bisa menutupi semua kebutuhan tersebut dengan mudah. Aplikasinya bisa melacak banyak pekerjaan secara paralel dalam waktu bersamaan, jadi seorang barista yang punya shift sore di kafe hari kerja dan jualan di pasar akhir pekan tetap bisa melihat kedua buku catatan itu dalam satu tampilan terpadu tanpa harus berpindah aplikasi. Setiap catatan yang sudah masuk bisa diekspor sebagai timesheet berformat CSV atau PDF, yang gampang dibagikan ke admin penggajian atau disimpan sebagai cadangan pribadi kamu sendiri kalau sewaktu-waktu dibutuhkan lagi. Seluruh aplikasi berjalan offline secara bawaan sejak pertama kali dipasang — jam kerjamu tersimpan aman di HP milikmu, tidak pernah diunggah ke server mana pun, dan antarmukanya tersedia dalam 14 bahasa yang berbeda untuk kenyamanan pengguna. Langganan sekali bayar atau tahunan membuka pekerjaan tanpa batas dan menghilangkan iklan; sementara itu, pelacak intinya sendiri tetap gratis dan bisa dipakai selamanya tanpa batasan fitur dasar.",
    ar: "تطبيق Work Hours Tracker هو تطبيق مجاني لتسجيل ساعات العمل على iOS، صُمم خصيصًا للعمال بنظام الساعة، والمستقلين، ومن ينظّمون ورديات العمل، ولكل من يحتاج إلى سجل دقيق بالساعات التي عملها والأجر الذي حصل عليه. يخلّصك التطبيق من دفتر الورق أو جدول البيانات المبعثر في أسفل الدرج. اضغط مرة عند بدء العمل، واضغط مرة أخرى عند انتهائه، وكل شيء آخر يحدث تلقائيًا: تُحسب الدقائق، وتُخصم الاستراحات، ويُطبَّق أجر العمل الإضافي، ويظلّ إجمالي ما تستحقه محدّثًا لحظة بلحظة. توفّر لك الإعدادات المسبقة لقوانين العمل في ١٣ دولة ومنطقة تحويل القواعد النظامية للعمل الليلي، والسقوف الأسبوعية، وأسس الأجر الإضافي إلى إعداد بنقرة واحدة؛ أما القواعد المخصّصة فتغطي كل ما عدا ذلك، وتمنحك مرونة كاملة لتطابق شروط عقدك. يتابع التطبيق عدة وظائف بالتوازي، فمثلًا الباريستا التي تعمل في مقهى خلال الأسبوع وفي سوق عطلة نهاية الأسبوع ترى سجلّي عملها في مكان واحد، مع فصل واضح بين كل وظيفة. يمكن تصدير كل سجل كملف CSV أو PDF، مما يسهل مشاركته مع مسؤول الرواتب أو الاحتفاظ به كنسخة احتياطية خاصة بك عند نهاية كل أسبوع أو شهر. التطبيق بأكمله يعمل دون اتصال بشكل افتراضي — تبقى ساعات عملك مخزّنة على هاتفك ولا تُرفع إلى أي خادم، والواجهة متاحة بـ ١٤ لغة لتخدمك أينما كنت. يتيح لك اشتراك لمرة واحدة أو اشتراك سنوي فتح وظائف غير محدودة وإزالة الإعلانات؛ بينما يظلّ التتبّع الأساسي مجانيًا للجميع.",
    fr: "Work Hours Tracker est une application gratuite de feuilles de temps pour iOS, conçue pour les salariés horaires, les travailleurs indépendants, les planificateurs de shifts et toute personne ayant besoin d'un relevé précis des heures travaillées et de la rémunération perçue. Elle remplace le carnet papier ou le tableur poussiéreux au fond du tiroir. Appuyez une fois pour pointer à l'arrivée, appuyez à nouveau pour pointer au départ, et le reste se fait automatiquement : les minutes sont calculées, les pauses sont déduites, les heures supplémentaires sont appliquées, et un total courant de ce qui vous est dû reste à jour en permanence. Des préréglages de droit du travail couvrant treize pays et régions transforment les règles légales sur le travail de nuit, les plafonds hebdomadaires et les taux d'heures supplémentaires en une configuration en un appui ; des règles personnalisées couvrent tout le reste. L'application suit plusieurs emplois en parallèle, de sorte qu'un barista avec un shift en semaine et un job au marché le week-end retrouve ses deux registres au même endroit. Chaque relevé peut être exporté en CSV ou en PDF, ce qui facilite le partage avec le service de paie ou la conservation d'une sauvegarde personnelle. L'application est entièrement hors ligne par défaut — vos heures sont stockées sur votre téléphone, jamais téléversées — et l'interface est disponible en 14 langues. Un abonnement unique ou annuel débloque un nombre illimité d'emplois et supprime les publicités ; le suivi de base reste gratuit.",
    de: "Work Hours Tracker ist eine kostenlose Stundenzettel-App für iOS, entwickelt für Schichtarbeiter, Freiberufler, Dienstplan-Planer und alle, die eine präzise Übersicht über ihre geleisteten Stunden und ihren tatsächlichen Verdienst benötigen. Die App ersetzt das vergilbte Notizbuch in der Schublade oder die unübersichtliche Tabelle, die seit Monaten niemand mehr wirklich geöffnet hat. Tippen Sie einmal, wenn Sie mit der Arbeit beginnen, und erneut, wenn Sie Feierabend machen – den Rest erledigt die App automatisch und zuverlässig im Hintergrund: Minuten werden präzise berechnet, Pausen sauber abgezogen, Überstunden korrekt berücksichtigt und ein laufender Saldo Ihres Verdiensts bleibt stets aktuell, ohne dass Sie selbst rechnen oder am Ende des Monats alles von Hand zusammenzählen müssen. Integrierte Arbeitsrechts-Voreinstellungen für dreizehn Länder und Regionen verwandeln gesetzliche Regelungen zu Nachtarbeit, wöchentlichen Höchstarbeitszeiten und Überstundensätzen in eine Einrichtung per Fingertipp; eigene Regeln decken alle Sonderfälle ab, die das jeweilige Gesetz nicht explizit abdeckt. Die App verwaltet mehrere Jobs parallel in getrennten Büchern, sodass eine Barista mit einer Wochentags-Schicht im Café und einem Wochenend-Job auf dem Wochenmarkt beide Abrechnungen an einem Ort sieht und am Monatsende sofort weiß, was insgesamt zusammenkommt und welcher Job sich tatsächlich lohnt. Jeder Eintrag lässt sich als CSV- oder PDF-Stundenzettel exportieren – ideal zum einfachen Teilen mit der Lohnbuchhaltung, als sauberer Nachweis gegenüber dem Arbeitgeber oder als eigene Sicherungskopie für die nächste Steuererklärung. Die gesamte App arbeitet standardmäßig offline: Ihre Arbeitsstunden bleiben auf Ihrem iPhone, werden niemals in eine Cloud hochgeladen und gehören allein Ihnen, ohne Tracking und ohne Werbenetzwerke. Die Benutzeroberfläche ist in 14 Sprachen verfügbar. Ein einmaliges oder jährliches Abonnement schaltet unbegrenzte Jobs frei und blendet Werbung dauerhaft aus; der Kern der Zeiterfassung bleibt dauerhaft kostenlos und ohne versteckte Kosten.",
    es: "Work Hours Tracker es una app gratuita de hojas de horas para iOS, pensada para trabajadores por hora, autónomos, personas con turnos rotativos y cualquiera que necesite un registro fiable de las horas trabajadas y el pago que ha generado. La app reemplaza el cuaderno de papel o la hoja de cálculo desordenada del fondo del cajón: toca una vez cuando empiezas tu jornada, toca otra vez cuando la terminas, y todo lo demás ocurre automáticamente. Los minutos se calculan, los descansos se descuentan, las horas extra se aplican y el total acumulado de lo que te deben se mantiene siempre actualizado, de modo que siempre sabes cuánto llevas ganado en el día, en la semana y en el mes. Las configuraciones de ley laboral para thirteen países y regiones convierten las reglas sobre trabajo nocturno, topes semanales y tarifas de horas extra en una configuración de un solo toque; para el resto, puedes crear reglas personalizadas que se ajusten a tu propio convenio o a tu forma de trabajar. La app hace seguimiento de varios trabajos en paralelo, de modo que un camarero con turno entre semana en un bar y un puesto los fines de semana en un mercado verá ambos libros contables en un mismo lugar, sin mezclarlos. Cada registro puede exportarse como hoja de horas en CSV o PDF, lo que facilita compartirla con el encargado de nóminas o guardarla como copia de seguridad personal para cualquier disputa futura. La app funciona sin conexión por defecto: tus horas se guardan en el teléfono, nunca se suben a ningún servidor, y la interfaz está disponible en 14 idiomas para adaptarse a dondequiera que trabajes. Una suscripción única o anual desbloquea trabajos sin límite y elimina los anúncios; el registrador principal, que cubre el día a día de la mayoría de usuarios, sigue siendo gratis.",
    pt: "O Work Hours Tracker é um aplicativo de folha de ponto grátis para iOS, pensado para quem trabalha por hora, freelancers, profissionais com turnos alternados e qualquer pessoa que precise de um controle preciso das horas trabalhadas e do pagamento recebido. Ele substitui aquele caderninho de papel ou aquela planilha bagunçada no fundo da gaveta. É só tocar uma vez quando você entra no trabalho e tocar de novo quando sai — o resto acontece automaticamente: os minutos são calculados, os intervalos descontados, as horas extras aplicadas, e um total acumulado do que você tem a receber fica sempre atualizado. Configurações prontas para a legislação trabalhista de treze países e regiões transformam regras de trabalho noturno, limites semanais e adicionais de hora extra em uma configuração rápida com um único toque; para os demais casos, é possível criar regras personalizadas. O app acompanha vários empregos ao mesmo tempo, então um barista que trabalha durante a semana em uma cafeteria e nos finais de semana em uma feira vê os dois controles no mesmo lugar, sem precisar trocar de tela. Cada registro pode ser exportado como CSV ou PDF, o que facilita o envio para o responsável pelo pagamento ou para guardar como backup pessoal ao fim do mês. O aplicativo funciona offline por padrão — suas horas ficam guardadas no celular, nunca são enviadas para nenhum servidor, e a interface está disponível em 14 idiomas para atender usuários em diferentes partes do mundo. Uma assinatura anual ou única libera empregos ilimitados e remove anúncios; o controle principal de ponto, que é o que você usa no dia a dia, continua totalmente grátis para sempre.",
    it: "Work Hours Tracker è un'app gratuita per iPhone dedicata a chi lavora a ore, ai liberi professionisti, a chi organizza turni e a chiunque abbia bisogno di un registro preciso delle ore lavorate e della paga maturata. L'app sostituisce il quaderno di carta o il foglio Excel dimenticato in fondo al cassetto. Tocca una volta quando inizi il turno, tocca di nuovo quando lo finisci, e tutto il resto succede in automatico: i minuti vengono calcolati, le pause sottratte, gli straordinari applicati, e il totale di quanto ti spetta resta sempre aggiornato. Le impostazioni predefinite basate sulle leggi sul lavoro di tredici paesi e regioni trasformano le regole su lavoro notturno, limiti settimanali e tariffe straordinari in una configurazione che si attiva con un tocco; per tutto il resto ci sono le regole personalizzate. L'app tiene traccia di più lavori in parallelo, così un barista con un turno infrasettimanale al bar e un ingaggio al mercato nel weekend vede entrambi i registri nello stesso posto. Ogni record si esporta in CSV o in PDF, così è facile condividerlo con l'ufficio paghe o tenerlo come copia personale. L'app funziona completamente offline — le tue ore restano sul telefono, non vengono mai caricate, e l'interfaccia è disponibile in quattordici lingue. Un abbonamento una tantum o annuale sblocca lavori illimitati e rimuove la pubblicità; il tracker di base resta gratuito.",
    ru: "Work Hours Tracker — это бесплатное iOS-приложение для учёта рабочего времени, созданное для почасовых сотрудников, фрилансеров, специалистов со сменным графиком и всех, кому нужен точный учёт отработанных часов и начисленной оплаты. Приложение заменяет бумажный блокнот и запутанные таблицы на нижнем ящике стола. Нажмите один раз, когда начинаете смену, и ещё раз, когда заканчиваете — всё остальное приложение сделает само: минуты пересчитываются, перерывы вычитаются, сверхурочные начисляются по правилам, а итоговая сумма к выплате всегда остаётся актуальной. Встроенные пресеты трудового законодательства для 13 стран и регионов превращают нормативы о ночной работе, недельных лимитах и ставках сверхурочных в настройку в одно нажатие; для остальных случаев можно задать собственные правила с учётом местной специфики. Приложение ведёт несколько мест работы параллельно, так что бариста с будничной сменой в кафе и подработкой на выходном рынке видит обе ведомости в одном месте и легко сравнивает, сколько заработал там и там. Каждую запись можно экспортировать в CSV или PDF — удобно отправить в бухгалтерию или оставить себе как резервную копию. Вся работа приложения по умолчанию оффлайн: ваши часы хранятся на iPhone и никуда не выгружаются, а интерфейс доступен на 14 языках. Разовая или годовая подписка открывает неограниченное количество мест работы и убирает рекламу; базовый трекер при этом остаётся бесплатным.",
    th: "Work Hours Tracker คือแอปบันทึกเวลาทำงานฟรีบน iOS ที่ออกแบบมาสำหรับคนทำงานรายชั่วโมง ฟรีแลนซ์ ผู้จัดตารางกะ และทุกคนที่ต้องการบันทึกจำนวนชั่วโมงทำงานและค่าตอบแทนที่ได้รับอย่างแม่นยำ แอปนี้จะมาแทนสมุดจดกระดาษหรือสเปรดชีตที่วุ่นวายในลิ้นชักค่ะ เพียงแตะครั้งเดียวเมื่อเริ่มงาน แล้วแตะอีกครั้งเมื่อเลิกงาน ส่วนที่เหลือจะเกิดขึ้นอัตโนมัติ: คำนวณนาที หักเวลาพัก คำนวณค่าล่วงเวลา และอัปเดตยอดรวมสิ่งที่คุณควรได้รับตลอดเวลา มีการตั้งค่ากฎหมายแรงงานสำเร็จรูปสำหรับ 13 ประเทศและภูมิภาค ที่แปลงข้อกำหนดเรื่องการทำงานกลางคืน เพดานรายสัปดาห์ และอัตราค่าล่วงเวลาให้เป็นการตั้งค่าเพียงแตะเดียว ส่วนกฎอื่นๆ สามารถกำหนดเองได้ตามต้องการ แอปติดตามหลายงานพร้อมกันได้ ดังนั้นบาริสต้าที่มีกะวันธรรมดาที่ร้านกาแฟและงานตลาดวันเสาร์-อาทิตย์จะเห็นบัญชีทั้งสองในที่เดียว ทุกบันทึกสามารถส่งออกเป็นไฟล์ CSV หรือ PDF ไทม์ชีต ทำให้แชร์กับเจ้าหน้าที่เงินเดือนหรือเก็บเป็นข้อมูลสำรองส่วนตัวได้ง่ายๆ ทั้งแอปทำงานแบบออฟไลน์เป็นค่าเริ่มต้น ชั่วโมงทำงานของคุณถูกจัดเก็บในโทรศัพท์เท่านั้น ไม่มีการอัปโหลด และอินเทอร์เฟซรองรับ 14 ภาษา การสมัครสมาชิกแบบครั้งเดียวหรือรายปีจะปลดล็อกงานไม่จำกัดและลบโฆษณา ส่วนตัวติดตามหลักยังคงฟรีค่ะ"
  },
  "image-to-pdf": {
    en: "Image to PDF is a focused mobile PDF toolkit that does six jobs and does them well, without ever sending your files to a server. You can convert one or many images into a single PDF in seconds, then merge several PDFs into one document, split a PDF into separate pages, lock a file behind a password, or unlock a PDF you already have the password for. The image-to-PDF converter accepts JPG, PNG, HEIC, WebP and TIFF, lets you choose page size, margins and orientation, and writes the finished PDF straight to your photo library or to the Files app. The merge tool combines pages from different sources into a single ordered document; the split tool extracts any selection of pages back out. The encryption screen uses the same AES-based algorithm as Adobe Reader, so a PDF you protect on your phone opens correctly on any desktop reader. Decryption takes a password you already know and removes the protection locally — the file is rewritten on your device, not on someone else's computer. Every operation runs on your phone, no upload, no account, no watermark, and the interface is available in fourteen languages. The app is free to use with optional Pro features for batch operations and ad removal.",
    zh: "Image to PDF 是一款专注好用的手机 PDF 工具箱，只做六件事，但每一件都做到位，而且从不把你的文件传到任何服务器。你可以在几秒内把一张或多张图片合成一个 PDF，把多份 PDF 合并成一份文档，把一个 PDF 拆分成独立页面，给文件加上密码保护，或者解开你已知密码的 PDF。图片转 PDF 支持 JPG、PNG、HEIC、WebP 和 TIFF 格式，页面尺寸、页边距和横竖方向都可以自由设置，转好的 PDF 直接写入相册或“文件”App。合并工具能把不同来源的页面整理成一份顺序清晰的文档；拆分工具则能把你选中的任意页面单独提取出来。加密功能采用与 Adobe Reader 相同的 AES 加密算法，在手机上加密的 PDF，在任何电脑阅读器上都能正常打开。解密时只需输入你已知的密码，保护就会在本地解除，文件在你自己的设备上重新写入，而不是跑到别人的电脑里。每一步操作都在手机上完成，不上传、不注册、无水印，界面支持 14 种语言。App 免费使用，另有可选的 Pro 功能，用于批量处理和去除广告。",
    "zh-TW": "Image to PDF 是一款功能精準的行動 PDF 工具組,專注做好六件事,所有檔案絕不上傳到任何伺服器。你可以把一張或多張圖片在幾秒內合併成單一 PDF,接著把多份 PDF 合併成一份文件、將 PDF 拆分成獨立頁面、為檔案加上密碼保護,或解開已知密碼的 PDF。圖片轉 PDF 功能支援 JPG、PNG、HEIC、WebP 與 TIFF 格式,讓你自由選擇頁面尺寸、邊界與方向,完成後的 PDF 直接存回照片圖庫或檔案 App。合併工具將不同來源的頁面組合成單一排序文件;拆分工具則能將任何頁面範圍抽出獨立成檔。加密畫面採用與 Adobe Reader 相同的 AES 加密演算法,在手機上保護的 PDF 能在任何電腦上正常開啟。解密時輸入你已知的密碼,保護機制便會在本機移除,檔案在你的裝置上重新寫入,絕不經過他人的電腦。每一道操作都在你的手機上執行,沒有上傳、不需帳號、無浮水印,介面支援 14 種語言。App 免費使用,另提供選購的 Pro 功能,適用於批次處理與去除廣告。",
    ja: "Image to PDFは、6つの機能を搭載したシンプルなモバイルPDFツールキットです。ファイルを決してサーバーに送信することなく、すべての処理を行います。複数の画像を1つのPDFにまとめて変換するのはわずか数秒。さらに、複数のPDFを1つの文書に結合したり、1つのPDFを複数のページに分割したり、パスワードでファイルをロックしたり、すでにご存じのパスワードでPDFのロックを解除したりできます。画像からPDFへの変換はJPG、PNG、HEIC、WebP、TIFFに対応し、用紙サイズ、余白、向きを自由に選んで、完成したPDFを写真ライブラリまたはFilesアプリに直接書き出せます。結合ツールは、異なる来源のページを1つの順序立てられた文書にまとめます。分割ツールは、任意の範囲のページを抽出できます。暗号化画面はAdobe Readerと同じAESベースのアルゴリズムを採用しているため、スマートフォンで保護したPDFはデスクトップのどのリーダーでも正しく開けます。復号化はすでにご存じのパスワードを使って端末内で行われ、ファイルは他社のサーバーではなく、お使いのデバイス上で書き換えられます。すべての操作はスマートフォン内で完結し、アップロードもアカウント作成も透かし挿入もなく、インターフェースは14言語に対応しています。バッチ処理や広告削除のPro機能はオプションで、基本機能は無料でご利用いただけます。",
    ko: "Image to PDF는 파일을 서버에 보내지 않고 6가지 작업을 깔끔하게 처리하는 모바일 PDF 도구입니다. 여러 이미지를 단 몇 초 만에 하나의 PDF로 변환하고, 여러 PDF를 하나로 합치거나 분리하거나, 비밀번호로 잠그거나 해제할 수 있습니다. JPG, PNG, HEIC, WebP, TIFF를 지원하며 페이지 크기, 여백, 방향을 자유롭게 선택해 사진 보관함이나 파일 앱에 바로 저장합니다. 합치기 도구는 여러 출처의 페이지를 순서대로 조합해 하나의 문서로 만들고, 분리 도구는 원하는 페이지만 골라 다시 뽑아냅니다. 암호화는 Adobe Reader와 동일한 AES 알고리즘을 사용해 휴대폰에서 보호한 PDF를 데스크톱 어디서든 문제없이 열어 볼 수 있습니다. 복호화도 기기 안에서만 처리되어 파일은 내 휴대폰에서 다시 작성됩니다. 모든 작업은 폰에서 실행되고 업로드, 계정, 워터마크는 없습니다. 인터페이스는 14개 언어로 제공되며 기본 사용은 무료이고, Pro 구독 시 대량 작업과 광고 제거가 가능합니다.",
    vi: "Image to PDF là bộ công cụ PDF trên di động tập trung vào sáu chức năng và làm trọn vẹn từng chức năng, không bao giờ gửi tệp của bạn lên máy chủ. Bạn có thể chuyển một hoặc nhiều hình ảnh thành một tệp PDF duy nhất chỉ trong vài giây, rồi gộp nhiều PDF lại thành một tài liệu, tách một PDF thành các trang riêng biệt, khóa tệp bằng mật khẩu, hoặc mở khóa một tệp PDF mà bạn đã có mật khẩu. Công cụ chuyển ảnh sang PDF chấp nhận các định dạng JPG, PNG, HEIC, WebP và TIFF, cho phép bạn chọn khổ trang, lề và hướng, sau đó ghi thẳng tệp PDF hoàn chỉnh vào thư viện ảnh hoặc ứng dụng Tệp. Công cụ gộp PDF kết hợp các trang từ nhiều nguồn khác nhau thành một tài liệu theo đúng thứ tự mong muốn; công cụ tách trích xuất bất kỳ tập trang nào bạn chọn ra ngoài. Màn hình mã hóa sử dụng cùng thuật toán dựa trên AES như Adobe Reader, nên một tệp PDF được bảo vệ trên điện thoại của bạn sẽ mở chính xác trên bất kỳ trình đọc nào trên máy tính. Quá trình giải mã dùng mật khẩu bạn đã biết và gỡ bỏ lớp bảo vệ ngay tại thiết bị — tệp được ghi lại trên điện thoại của bạn, không phải trên máy tính của ai khác. Mọi thao tác đều chạy trên điện thoại của bạn, không tải lên, không cần tài khoản, không có watermark, và giao diện có sẵn bằng 14 ngôn ngữ. Ứng dụng miễn phí sử dụng, kèm các tính năng Pro tùy chọn cho thao tác hàng loạt và xóa quảng cáo.",
    id: "Image to PDF adalah toolkit PDF mobile yang fokus menjalankan enam pekerjaan utama dengan sangat baik, tanpa pernah mengirim file kamu ke server mana pun di luar perangkat. Kamu bisa mengubah satu gambar atau banyak gambar sekaligus menjadi satu PDF utuh dalam hitungan detik, lalu menggabungkan beberapa PDF berbeda menjadi satu dokumen tunggal, membagi satu PDF menjadi halaman-halaman terpisah sesuai kebutuhan, mengunci file dengan kata sandi untuk perlindungan ekstra, atau membuka kunci PDF yang sebenarnya sudah kamu punya kata sandinya tetapi lupa cara membukanya. Konverter image-to-PDF ini menerima format JPG, PNG, HEIC, WebP, dan TIFF, memungkinkan kamu memilih ukuran halaman, margin, dan orientasi sesuai kebutuhan spesifik, lalu menulis PDF hasilnya langsung ke perpustakaan foto pribadi atau ke app Files di iPhone. Alat merge menggabungkan halaman dari sumber-sumber berbeda menjadi satu dokumen terurut rapi sesuai urutan yang kamu tentukan; sementara alat split mengekstrak pilihan halaman tertentu kembali menjadi file terpisah yang siap dipakai. Layar enkripsi memakai algoritma berbasis AES yang sama persis seperti yang dipakai oleh Adobe Reader, jadi PDF yang kamu kunci dan proteksi di HP dijamin akan terbuka benar di pembaca PDF desktop mana pun di seluruh dunia tanpa masalah kompatibilitas. Fitur dekripsi cukup memakai kata sandi yang sudah kamu ketahui dan menghapus proteksinya secara lokal — file akan ditulis ulang langsung di perangkatmu sendiri, bukan diproses dulu di komputer orang lain. Setiap operasi berjalan sepenuhnya di HP: tidak ada unggahan, tidak butuh akun, tidak ada watermark mengganggu, dan antarmukanya tersedia dalam 14 bahasa. Aplikasi ini gratis dipakai dengan fitur Pro opsional untuk pengguna yang sering melakukan operasi batch dan ingin menghilangkan iklan.",
    ar: "تطبيق Image to PDF هو مجموعة أدوات PDF محمولة مركّزة، تنجز ست مهام وتؤديها بإتقان، دون أن ترسل ملفاتك إلى أي خادم. يمكنك تحويل صورة واحدة أو عدة صور إلى ملف PDF واحد خلال ثوانٍ، ثم دمج عدة ملفات PDF في مستند واحد، أو تقسيم ملف PDF إلى صفحات منفصلة، أو حماية ملف بكلمة مرور، أو فتح قفل ملف PDF لديك كلمة المرور الخاصة به. يقبل محوّل الصور إلى PDF صيغ JPG وPNG وHEIC وWebP وTIFF، ويتيح لك اختيار حجم الصفحة والهوامش والاتجاه، ويحفظ ملف PDF النهائي مباشرةً في مكتبة الصور أو في تطبيق الملفات. تجمع أداة الدمج الصفحات من مصادر مختلفة في مستند واحد مرتّب حسب رغبتك، بينما تستخرج أداة التقسيم أي مجموعة صفحات تريدها وترتّبها بسرعة. تستخدم شاشة التشفير نفس خوارزمية AES المعتمدة في Adobe Reader، لذا فإن أي ملف PDF تحميه على هاتفك يفتح بشكل صحيح على أي قارئ على الحاسوب، بصرف النظر عن النظام المستخدم. أما فك التشفير فيتطلب كلمة مرور تعرفها مسبقًا ويزيل الحماية محليًا — إذ تُعاد كتابة الملف على جهازك لا على حاسوب شخص آخر، مما يضمن خصوصية تامة. كل عملية تتم على هاتفك، دون رفع، ودون حساب، ودون علامة مائية، والواجهة متاحة بـ ١٤ لغة. التطبيق مجاني الاستخدام مع ميزات Pro اختيارية للعمليات المجمّعة وإزالة الإعلانات.",
    fr: "Image to PDF est une boîte à outils PDF mobile, ciblée et efficace, qui accomplit six missions sans jamais transmettre vos fichiers à un serveur. Vous pouvez convertir une ou plusieurs images en un seul PDF en quelques secondes, puis fusionner plusieurs PDF en un document unique, diviser un PDF en pages séparées, verrouiller un fichier par mot de passe, ou déverrouiller un PDF dont vous connaissez déjà le mot de passe. Le convertisseur image vers PDF accepte les formats JPG, PNG, HEIC, WebP et TIFF, vous permet de choisir la taille de page, les marges et l'orientation, et écrit le PDF final directement dans votre bibliothèque de photos ou dans l'app Fichiers. L'outil de fusion combine des pages de différentes sources en un document unique et ordonné ; l'outil de division extrait n'importe quelle sélection de pages. L'écran de chiffrement utilise le même algorithme basé sur AES qu'Adobe Reader, de sorte qu'un PDF protégé sur votre téléphone s'ouvre correctement dans n'importe quel lecteur de bureau. Le déchiffrement prend un mot de passe que vous connaissez déjà et supprime la protection localement — le fichier est réécrit sur votre appareil, et non sur l'ordinateur de quelqu'un d'autre. Chaque opération s'exécute sur votre téléphone : pas de téléversement, pas de compte, pas de filigrane, et l'interface est disponible en 14 langues. L'application est gratuite, avec des fonctionnalités Pro en option pour les opérations par lots et la suppression des publicités.",
    de: "Image to PDF ist ein mobiles PDF-Werkzeug, das sechs alltägliche Aufgaben zuverlässig erledigt – ohne jemals Ihre Dateien an einen fremden Server zu senden oder ein Konto vorauszusetzen. Sie können ein einzelnes Bild oder beliebig viele Bilder in wenigen Sekunden in ein PDF umwandeln, mehrere vorhandene PDFs zu einem einzigen, sauber geordneten Dokument zusammenfügen, ein bestehendes PDF in einzelne Seiten oder Seitensequenzen aufteilen, eine Datei mit einem Passwort zuverlässig schützen oder umgekehrt ein bestehendes PDF entsperren, dessen Passwort Sie bereits kennen. Der Bild-zu-PDF-Konverter akzeptiert JPG, PNG, HEIC, WebP und TIFF, lässt Sie Seitenformat, Ränder und Ausrichtung frei wählen und schreibt das fertige PDF direkt in Ihre Fotos-Bibliothek oder in die Dateien-App, ohne Umweg über irgendeinen Zwischenspeicher im Netz. Das Zusammenführungs-Werkzeug kombiniert Seiten aus unterschiedlichsten Quellen zu einem übersichtlichen Gesamtdokument; das Teilen-Werkzeug extrahiert beliebige Seitenfolgen wieder heraus und erlaubt es, gezielt nur die wirklich benötigten Seiten zu sichern oder weiterzugeben. Die Verschlüsselung nutzt denselben AES-basierten Algorithmus wie Adobe Reader, sodass ein auf dem iPhone geschütztes PDF in jedem Desktop-Programm korrekt geöffnet wird und der Empfänger nichts extra installieren muss, um es lesen zu können. Die Entschlüsselung verwendet ein bekanntes Passwort und entfernt den Schutz lokal – die Datei wird auf Ihrem Gerät neu geschrieben, nicht auf einem fremden Computer, und bleibt so jederzeit unter Ihrer Kontrolle. Jeder Vorgang läuft vollständig auf Ihrem iPhone, ohne Upload, ohne Konto, ohne Wasserzeichen, und die Benutzeroberfläche ist in 14 Sprachen verfügbar. Die App ist kostenlos nutzbar; optionale Pro-Funktionen erweitern sie um komfortable Stapelverarbeitung für große Mengen und das dauerhafte Entfernen von Werbung.",
    es: "Image to PDF es un kit de herramientas móvil enfocado en PDF que hace seis tareas y las hace bien, sin enviar nunca tus archivos a ningún servidor. Puedes convertir una o varias imágenes en un único PDF en segundos, luego fusionar varios PDF en un solo documento, dividir un PDF en páginas separadas, proteger un archivo con contraseña o desbloquear un PDF del que ya tienes la clave. El conversor de imagen a PDF acepta JPG, PNG, HEIC, WebP y TIFF, te permite elegir el tamaño de página, los márgenes y la orientación, y guarda el PDF terminado directamente en tu fototeca o en la app Archivos, sin pasos intermedios. La herramienta de fusión combina páginas de distintos orígenes en un único documento ordenado manteniendo el orden que prefieras; la de división extrae cualquier selección de páginas y crea archivos individuales con un solo toque. La pantalla de cifrado utiliza el mismo algoritmo AES compatible con Adobe Reader, así que un PDF que protejas en tu teléfono se abrirá correctamente en cualquier lector de escritorio, sin sorpresas ni mensajes de error. El descifrado toma una contraseña que ya conoces y elimina la protección localmente: el archivo se reescribe en tu dispositivo, no en el ordenador de otro. Cada operación se ejecuta en tu teléfono, sin subidas, sin cuenta, sin marca de agua y sin registros, y la interfaz está disponible en 14 idiomas. La app es gratis, con funciones Pro opcionales para operaciones por lotes grandes, flujos automatizados y eliminación de anúncios.",
    pt: "O Image to PDF é um kit de ferramentas de PDF focado no celular, que faz seis tarefas e faz todas bem, sem nunca enviar seus arquivos para um servidor remoto. Você pode converter uma ou várias imagens em um único PDF em poucos segundos, depois juntar vários PDFs em um documento só, dividir um PDF em páginas separadas, proteger um arquivo com senha ou remover a proteção de um PDF cuja senha você já conhece. O conversor de imagem para PDF aceita JPG, PNG, HEIC, WebP e TIFF, permite escolher o tamanho da página, as margens e a orientação, e grava o PDF pronto direto na sua biblioteca de fotos ou no app Arquivos do iPhone. A ferramenta de junção combina páginas de fontes diferentes em um único documento ordenado; a ferramenta de divisão extrai qualquer seleção de páginas de volta, sem perder a qualidade original. A tela de criptografia usa o mesmo algoritmo baseado em AES do Adobe Reader, então um PDF protegido no seu celular abre corretamente em qualquer leitor de desktop, seja no Mac, no Windows ou no Linux. A descriptografia usa uma senha que você já sabe e remove a proteção localmente — o arquivo é reescrito no seu aparelho, e não no computador de ninguém. Cada operação roda no seu celular, sem envio de dados, sem conta, sem marca d'água, e a interface está disponível em 14 idiomas. O app é grátis para usar, com recursos Pro opcionais para operações em lote e remoção de anúncios.",
    it: "Image to PDF è una cassetta degli attrezzi per PDF che fa sei cose e le fa bene, senza mai mandare i tuoi file a un server. Puoi convertire una o molte immagini in un unico PDF in pochi secondi, poi unire più PDF in un documento solo, dividere un PDF in pagine separate, bloccare un file con una password o sbloccare un PDF di cui conosci già la password. Il convertitore immagine-in-PDF accetta JPG, PNG, HEIC, WebP e TIFF, ti lascia scegliere formato pagina, margini e orientamento, e scrive il PDF finale direttamente nella libreria foto o nell'app File. Lo strumento di unione combina pagine da fonti diverse in un documento ordinato; lo strumento di divisione estrae qualsiasi selezione di pagine. La schermata di crittografia usa lo stesso algoritmo AES di Adobe Reader, così un PDF che proteggi sul telefono si apre correttamente su qualsiasi lettore desktop. La decrittazione prende una password che già conosci e rimuove la protezione localmente — il file viene riscritto sul tuo dispositivo, non sul computer di qualcun altro. Ogni operazione gira sul telefono: nessun upload, nessun account, nessuna filigrana, e l'interfaccia è disponibile in quattordici lingue. L'app è gratuita con funzioni Pro opzionali per le operazioni in batch e la rimozione della pubblicità.",
    ru: "Image to PDF — это компактный мобильный набор инструментов для работы с PDF, который выполняет шесть задач и выполняет их хорошо, при этом ни один ваш файл не отправляется на сервер. Вы можете за секунды преобразовать одно или несколько изображений в единый PDF, затем объединить несколько PDF в один документ, разделить PDF на отдельные страницы, поставить на файл пароль или снять защиту с PDF, пароль которого вам уже известен. Конвертер изображений в PDF принимает форматы JPG, PNG, HEIC, WebP и TIFF, позволяет выбрать размер страницы, поля и ориентацию и сохраняет готовый PDF напрямую в вашу фотобиблиотеку или в приложение «Файлы». Инструмент слияния собирает страницы из разных источников в один упорядоченный документ, а инструмент разделения извлекает любую выбранную группу страниц. Экран шифрования использует тот же алгоритм на основе AES, что и Adobe Reader, поэтому PDF, защищённый на вашем iPhone, корректно открывается в любом десктопном просмотрщике. Дешифровка принимает известный вам пароль и снимает защиту локально — файл перезаписывается на вашем устройстве, а не на чужом компьютере. Все операции выполняются на iPhone: ни загрузки, ни аккаунта, ни водяных знаков, а интерфейс доступен на 14 языках. Приложение бесплатно, а опциональные возможности Pro открывают пакетную обработку и удаление рекламы.",
    th: "Image to PDF คือชุดเครื่องมือ PDF บนมือถือที่ทำงานหกอย่างได้อย่างดีเยี่ยม โดยไม่ส่งไฟล์ของคุณไปยังเซิร์ฟเวอร์เลย คุณสามารถแปลงภาพหนึ่งภาพหรือหลายภาพเป็น PDF ไฟล์เดียวได้ในไม่กี่วินาที จากนั้นรวม PDF หลายไฟล์เป็นเอกสารเดียว แยก PDF ออกเป็นหน้าๆ ล็อกไฟล์ด้วยรหัสผ่าน หรือปลดล็อก PDF ที่คุณมีรหัสผ่านอยู่แล้ว เครื่องมือแปลงภาพเป็น PDF รองรับ JPG, PNG, HEIC, WebP และ TIFF ให้คุณเลือกขนาดหน้า ขอบ และการวางแนว พร้อมบันทึก PDF ที่เสร็จแล้วลงในคลังภาพหรือแอปไฟล์ได้โดยตรง เครื่องมือรวมไฟล์จะรวมหน้าจากแหล่งต่างๆ เป็นเอกสารเรียงลำดับเดียว ส่วนเครื่องมือแยกไฟล์จะดึงหน้าที่เลือกกลับออกมา หน้าจอเข้ารหัสใช้อัลกอริทึมแบบ AES เช่นเดียวกับ Adobe Reader ดังนั้น PDF ที่คุณป้องกันบนโทรศัพท์จะเปิดได้อย่างถูกต้องในโปรแกรมอ่าน PDF บนเดสก์ท็อปทุกเครื่อง การถอดรหัสใช้รหัสผ่านที่คุณรู้อยู่แล้วและลบการป้องกันในเครื่อง ไฟล์จะถูกเขียนใหม่บนอุปกรณ์ของคุณ ไม่ใช่บนคอมพิวเตอร์ของคนอื่น ทุกการทำงานทำบนโทรศัพท์ของคุณ ไม่มีการอัปโหลด ไม่ต้องสร้างบัญชี ไม่มีลายน้ำ และอินเทอร์เฟซรองรับ 14 ภาษา แอปใช้งานได้ฟรีพร้อมฟีเจอร์ Pro เสริมสำหรับการทำงานแบบแบตช์และลบโฆษณาค่ะ"
  },
  "image-converter": {
    en: "Image Converter is a complete mobile image toolkit for anyone who needs to rework a photo on their phone without uploading it anywhere. It converts between JPG, JPEG, PNG, WebP, BMP and TIFF, with batch support so a folder of HEIC exports can become a folder of web-ready JPGs in one pass. Beyond format conversion, the app includes a compressor that reduces file size at a chosen quality, a resizer that scales by pixel or by longest edge, a cropper with aspect-ratio presets for social posts, a rotation tool that handles both single images and bulk batches, and a stitch tool that joins several photos into a long screenshot or a grid. Every tool runs locally: the image data never leaves the phone, the new file is written straight back to your library, and there is no account to create. The interface is available in fourteen languages, the core conversion tools are free, and a small Pro subscription removes ads and unlocks the largest batch sizes. Image Converter is built for the moments when you need the photo to be a different shape, a different format, or a different size — and you need it now, on the phone in your hand.",
    zh: "Image Converter 是一款功能齐全的手机图片工具箱，让你无需把照片上传到任何地方，就能直接在手机上完成处理。它支持 JPG、JPEG、PNG、WebP、BMP 和 TIFF 之间的互转，还支持批量操作，整整一个文件夹的 HEIC 照片可以一次性转成适合网页的 JPG。除了格式转换，App 还内置了压缩工具，可按指定画质缩小文件体积；缩放工具支持按像素或按最长边调整；裁剪工具提供适配各类社交平台的比例预设；旋转工具单张和批量都能搞定；拼接工具则能把多张照片拼成长截图或宫格图。所有功能都在本地运行：图片数据从不离开手机，新文件直接写回你的相册，全程无需注册账号。界面支持 14 种语言，核心转换功能免费使用，小额 Pro 订阅可去除广告并解锁最大批量额度。Image Converter 就是为那些“需要马上换个尺寸、换个格式、换个形状”的时刻而生——用你手里的这台手机，现在就能搞定。",
    "zh-TW": "Image Converter 是一款功能完整的行動圖片工具組,讓你無需上傳任何檔案,就能在手機上直接編輯照片。支援 JPG、JPEG、PNG、WebP、BMP 與 TIFF 之間的格式轉換,並具備批次處理能力,讓一整資料夾的 HEIC 檔案一次轉成網頁用的 JPG。除了格式轉換,App 還內建壓縮器,可依指定品質縮減檔案大小;縮放工具可依像素或最長邊進行調整;裁切工具提供社群貼文的長寬比預設;旋轉工具同時支援單張與大量批次;拼接工具則能將多張照片組成長截圖或網格圖。每一項功能都在本機執行:圖片資料從不離開手機,新檔案直接寫回你的圖庫,完全不需要建立帳號。介面支援 14 種語言,核心轉換功能免費使用,小型 Pro 訂閱可去除廣告並解鎖最大批次容量。Image Converter 專為那些需要立即改變照片形狀、格式或尺寸的時刻而生,在你掌中的手機上,馬上就能完成。",
    ja: "Image Converterは、写真をどこにもアップロードすることなくスマートフォン上で加工したい方のための、モバイル画像加工ツールキットです。JPG、JPEG、PNG、WebP、BMP、TIFFの間の形式変換に対応し、バッチ処理もサポートしているため、HEIC形式で書き出された画像フォルダを、一度の操作でWeb用のJPGフォルダに変換できます。形式変換だけでなく、画質を選んでファイルサイズを削減できる圧縮機能、ピクセル単位または長辺指定でスケール変更できるリサイズ機能、SNS投稿向けのアスペクト比プリセット付きのクロップ機能、1枚単位と一括処理の両方に対応する回転機能、複数の写真を1枚の長いスクリーンショットまたはグリッドに結合するスティッチ機能も搭載しています。すべてのツールがローカルで動作し、画像データは端末から一切外部に出ません。新しいファイルはライブラリに直接書き戻され、作成が必要なアカウントもありません。インターフェースは14言語に対応しており、基本的な変換ツールは無料でお使いいただけます。Proのサブスクリプション（少額）を契約すると、広告が削除され、最大バッチサイズが適用されます。Image Converterは、写真を別の形状、別の形式、別のサイズに、今すぐ手元のスマートフォンで変換する必要がある瞬間のために作られました。",
    ko: "Image Converter는 사진을 어디에도 업로드하지 않고 휴대폰에서 바로 다룰 수 있는 올인원 이미지 도구입니다. JPG, JPEG, PNG, WebP, BMP, TIFF 사이의 변환을 지원하며, HEIC 폴더 한 묶음도 한 번에 웹용 JPG로 바꿀 수 있습니다. 포맷 변환뿐 아니라 원하는 화질로 파일 크기를 줄이는 압축, 픽셀 또는 긴 변 기준 리사이즈, SNS 종횡비 프리셋이 있는 자르기, 단일·대량 회전, 여러 사진을 이어 붙이는 스티치까지 갖추고 있습니다. 모든 작업이 기기 안에서 처리되며 이미지 데이터는 휴대폰 밖으로 나가지 않고, 새 파일은 보관함에 바로 저장되며 만들 계정도 없습니다. 인터페이스는 14개 언어로 제공되고 핵심 변환 도구는 무료이며, Pro 구독으로 광고 제거와 최대 배치 크기를 이용하실 수 있습니다. 사진의 모양, 포맷, 크기가 딱 필요한 모습이어야 할 때 손에 쥔 휴대폰에서 바로 해결해 드립니다.",
    vi: "Image Converter là bộ công cụ hình ảnh trên di động toàn diện dành cho bất kỳ ai cần chỉnh sửa một bức ảnh ngay trên điện thoại mà không cần tải ảnh lên bất kỳ đâu. Ứng dụng cho phép chuyển đổi qua lại giữa các định dạng JPG, JPEG, PNG, WebP, BMP và TIFF, hỗ trợ xử lý hàng loạt để cả một thư mục ảnh HEIC có thể thành cả một thư mục JPG sẵn sàng cho web chỉ trong một lần chạy. Ngoài chuyển đổi định dạng, ứng dụng còn có công cụ nén giúp giảm dung lượng theo mức chất lượng bạn chọn, công cụ thay đổi kích thước theo pixel hoặc theo cạnh dài nhất, công cụ cắt ảnh với các tỉ lệ cài sẵn cho bài đăng mạng xã hội, công cụ xoay ảnh xử lý cả ảnh đơn lẫn hàng loạt, và công cụ ghép ảnh nối nhiều bức ảnh thành một ảnh chụp màn hình dài hoặc thành một lưới. Mọi công cụ đều chạy ngay trên thiết bị: dữ liệu hình ảnh không rời khỏi điện thoại, tệp mới được ghi thẳng trở lại thư viện của bạn, và không cần tạo tài khoản. Giao diện có sẵn bằng 14 ngôn ngữ, các công cụ chuyển đổi cốt lõi miễn phí, và một gói đăng ký Pro nhỏ sẽ xóa quảng cáo cùng mở khóa kích thước hàng loạt lớn nhất. Image Converter được tạo ra cho những lúc bạn cần bức ảnh có hình dạng khác, định dạng khác hoặc kích thước khác — và bạn cần ngay bây giờ, ngay trên chiếc điện thoại trong tay bạn.",
    id: "Image Converter adalah toolkit gambar mobile lengkap yang dirancang khusus buat siapa pun yang perlu mengubah, memperbaiki, atau menyesuaikan foto langsung di HP tanpa harus mengunggahnya dulu ke layanan pihak ketiga mana pun di internet. Aplikasi ini mampu mengonversi antara format JPG, JPEG, PNG, WebP, BMP, dan TIFF, lengkap dengan dukungan fitur batch supaya satu folder penuh berisi ekspor HEIC dari kamera iPhone bisa langsung berubah menjadi folder berisi JPG yang siap dipakai di web dalam sekali jalan tanpa proses yang ribet. Selain fitur konversi format murni, aplikasinya juga mencakup kompresor yang memperkecil ukuran file pada tingkat kualitas pilihanmu sendiri, fitur resize yang mengubah dimensi gambar berdasarkan jumlah piksel atau sisi terpanjang foto, cropper dengan preset rasio aspek untuk berbagai kebutuhan unggahan ke media sosial, alat rotasi yang menangani gambar tunggal maupun banyak gambar sekaligus dalam satu operasi, dan fitur stitch yang menyatukan beberapa foto menjadi satu screenshot panjang atau grid yang rapi untuk kebutuhan dokumentasi visual. Setiap alat dalam aplikasi ini berjalan secara lokal di perangkatmu sendiri tanpa ketergantungan server: data gambar tidak pernah meninggalkan HP, file baru ditulis langsung kembali ke perpustakaan foto milikmu, dan sama sekali tidak perlu bikin akun atau login apa pun sebelum mulai bekerja. Antarmukanya tersedia dalam 14 bahasa, semua alat konversi intinya gratis dipakai tanpa batas, dan langganan Pro kecil akan menghilangkan iklan sepenuhnya sekaligus membuka ukuran batch terbesar untuk para pengguna mahir. Image Converter pada dasarnya dibuat khusus untuk momen-momen ketika kamu butuh foto itu punya bentuk, format, atau ukuran yang berbeda dari aslinya — dan kamu butuh perubahan itu sekarang juga, langsung dari HP yang sedang kamu pegang saat itu.",
    ar: "تطبيق Image Converter هو مجموعة أدوات صور متكاملة على الهاتف لمن يحتاج إلى تعديل صورة على جهازه دون رفعها إلى أي مكان. يحوّل التطبيق بين صيغ JPG وJPEG وPNG وWebP وBMP وTIFF، مع دعم المعالجة المجمّعة ليحوّل مجلد كامل من صور HEIC إلى مجلد من صور JPG الجاهزة للويب في عملية واحدة دون عناء. وإلى جانب تحويل الصيغ، يضمّ التطبيق ضاغطًا يقلل حجم الملف بالجودة التي تختارها، ومغيّر حجم يصغّر الصورة بالبكسل أو بأطول ضلع، ومقصّاصًا يتضمّن نسب أبعاد جاهزة لمنشورات التواصل الاجتماعي، وأداة تدوير تتعامل مع الصور المفردة والدفعات بضغطة واحدة، وأداة دمج تجمع عدة صور في لقطة شاشة طويلة أو شبكة مرتّبة بشكل أنيق. كل أداة تعمل محليًا على جهازك: لا تغادر بيانات الصور هاتفك أبدًا، وتُحفظ الصورة الجديدة مباشرةً في مكتبتك، ولا حاجة لإنشاء أي حساب أو تسجيل دخول أو ربط بأي خدمة سحابية خارجية على الإطلاق. الواجهة متاحة بـ ١٤ لغة، وأدوات التحويل الأساسية مجانية للجميع، واشتراك Pro صغير يزيل الإعلانات ويفتح أكبر أحجام الدفعات للمهام الاحترافية والعمليات الكبيرة المتكررة. صُمم Image Converter للحظات التي تحتاج فيها إلى أن تكون الصورة بشكل مختلف، أو صيغة مختلفة، أو حجم مختلف — وتحتاج إليها الآن، على الهاتف في يدك، بعيدًا عن أي خادم.",
    fr: "Image Converter est une boîte à outils d'image complète pour mobile, pensée pour quiconque a besoin de retravailler une photo sur son téléphone sans la téléverser nulle part. Elle convertit entre JPG, JPEG, PNG, WebP, BMP et TIFF, avec prise en charge des lots : un dossier d'exportations HEIC peut ainsi devenir en une seule passe un dossier de JPG prêts pour le web. Au-delà de la conversion de format, l'application inclut un compresseur qui réduit la taille du fichier selon une qualité choisie, un redimensionneur qui ajuste en pixels ou selon le côté le plus long, un recadreur avec des préréglages de ratios pour les publications sur les réseaux sociaux, un outil de rotation qui gère aussi bien les images uniques que les lots, et un outil d'assemblage qui joint plusieurs photos en une longue capture d'écran ou en une grille. Chaque outil s'exécute localement : les données de l'image ne quittent jamais le téléphone, le nouveau fichier est réécrit directement dans votre bibliothèque, et il n'y a aucun compte à créer. L'interface est disponible en 14 langues, les outils de conversion principaux sont gratuits, et un petit abonnement Pro supprime les publicités et débloque les tailles de lot les plus importantes. Image Converter est faite pour ces moments où vous avez besoin que la photo change de forme, de format ou de taille — et où vous en avez besoin maintenant, sur le téléphone dans votre main.",
    de: "Image Converter ist ein vollständiges mobiles Bild-Werkzeug für alle, die ein Foto direkt auf dem iPhone bearbeiten möchten, ohne es irgendwo hochzuladen oder ein Konto anzulegen. Die App konvertiert zuverlässig zwischen JPG, JPEG, PNG, WebP, BMP und TIFF, mit komfortabler Stapelverarbeitung, sodass ein ganzer Ordner voller HEIC-Exports in einem einzigen Durchgang zu einem Ordner webfertiger JPGs wird, ohne dass Sie jedes Bild einzeln anfassen oder umständlich exportieren müssen. Neben der reinen Formatkonvertierung bietet die App einen effizienten Kompressor, der die Dateigröße bei frei wählbarer Qualität deutlich reduziert, einen präzisen Skalierer, der nach exakten Pixeln oder nach der längsten Kante anpasst, einen sauber arbeitenden Zuschneider mit Seitenverhältnis-Voreinstellungen für gängige Social-Media-Plattformen, ein Werkzeug zum geraden Drehen einzelner Bilder oder ganzer Stapel sowie ein vielseitiges Stitching-Werkzeug, das mehrere Fotos nahtlos zu einem langen Screenshot oder einer übersichtlichen Bildcollage zusammenfügt. Jedes Werkzeug läuft vollständig lokal auf dem Gerät: Die Bilddaten verlassen das iPhone zu keinem Zeitpunkt, die neue Datei wird direkt in die Bibliothek zurückgeschrieben, und es entfällt jedes Risiko eines versehentlichen Datenlecks über einen fremden Dienst. Die Benutzeroberfläche ist in 14 Sprachen verfügbar, die Kernkonvertierungsfunktionen sind kostenlos und ohne versteckte Hürden, und ein kleines Pro-Abonnement entfernt die Werbung dauerhaft und schaltet die größten Stapelgrößen für Power-User frei, die regelmäßig hunderte Bilder auf einmal verarbeiten. Image Converter ist für genau die Momente gemacht, in denen ein Foto ein anderes Format, eine andere Form oder eine andere Größe braucht – und das sofort, verlässlich und ohne Internetverbindung, direkt auf dem iPhone in Ihrer Hand, mit wenigen Tipp-Gesten erledigt.",
    es: "Image Converter es un kit completo de herramientas de imagen para móvil, pensado para quien necesita retocar una foto en su teléfono sin subirla a ningún sitio. Convierte entre JPG, JPEG, PNG, WebP, BMP y TIFF, con soporte por lotes para que una carpeta de exportaciones HEIC se convierta en una carpeta de JPG listos para la web en una sola pasada, sin tener que procesarlas una por una. Más allá de la conversión de formato, la app incluye un compresor que reduce el tamaño manteniendo la calidad que elijas, un redimensionador que escala por píxeles o por el lado más largo, un recortador con preajustes de relación de aspecto para publicaciones en redes, una herramienta de rotación que maneja imágenes individuales y lotes completos, y una herramienta de unión que combina varias fotos en una captura larga o en una cuadrada perfecta. Cada herramienta funciona en local: los datos de la imagen nunca salen del teléfono, el nuevo archivo se guarda directo en tu biblioteca y no hay cuenta que crear ni permisos en la nube que conceder. La interfaz está disponible en 14 idiomas, las herramientas básicas de conversión son gratis, y una pequeña suscripción Pro elimina los anúncios y desbloquea los tamaños de lote más grandes, los formatos adicionales y el acceso anticipado a nuevas funciones. Image Converter está pensada para esos momentos en los que necesitas que la foto tenga otra forma, otro formato u otro tamaño, y lo necesitas ahora, en el teléfono que tienes en la mano.",
    pt: "O Image Converter é um kit completo de imagens para celular, ideal para quem precisa editar uma foto no próprio aparelho sem enviar nada para a internet. Ele converte entre JPG, JPEG, PNG, WebP, BMP e TIFF, com suporte a lote em uma única passada: uma coleção inteira de arquivos HEIC pode virar uma pasta de JPGs prontos para a web sem complicação. Além da conversão de formato, o app inclui um compressor que reduz o tamanho do arquivo com a qualidade que você definir, um redimensionador que ajusta por pixel ou pela maior borda, um recortador com proporções prontas para postagens em redes sociais como Instagram e Twitter, uma ferramenta de rotação que funciona em imagens únicas ou em lote, e uma ferramenta de junção que junta várias fotos em uma captura de tela longa ou em uma grade personalizada. Cada ferramenta roda localmente no seu aparelho: os dados da imagem nunca saem do celular, o novo arquivo é gravado direto de volta na sua biblioteca de fotos, e não é preciso criar conta nem fazer login para começar a usar. A interface está disponível em 14 idiomas, as ferramentas principais de conversão são gratuitas, e uma assinatura Pro pequena remove anúncios e libera os tamanhos maiores de lote para quem precisa processar dezenas de arquivos de uma só vez. O Image Converter foi feito para os momentos em que você precisa que a foto tenha outro formato, outro tamanho ou outra proporção — e precisa agora, no celular que está na sua mão.",
    it: "Image Converter è una cassetta degli attrezzi completa per le immagini su telefono, pensata per chi deve rielaborare una foto senza caricarla da nessuna parte. Converte tra JPG, JPEG, PNG, WebP, BMP e TIFF, con supporto batch: una cartella di export HEIC diventa una cartella di JPG pronte per il web in un solo passaggio. Oltre alla conversione di formato, l'app include un compressore che riduce la dimensione del file a una qualità scelta, un ridimensionatore che scala per pixel o per lato più lungo, un ritaglio con proporzioni preimpostate per i post social, uno strumento di rotazione che gestisce sia le immagini singole sia i batch, e uno strumento di cucitura che unisce più foto in uno screenshot lungo o in una griglia. Ogni strumento gira in locale: i dati delle immagini non lasciano mai il telefono, il nuovo file viene scritto direttamente nella libreria, e non c'è nessun account da creare. L'interfaccia è disponibile in quattordici lingue, gli strumenti di conversione base sono gratuiti, e un piccolo abbonamento Pro rimuove la pubblicità e sblocca le dimensioni batch più grandi. Image Converter è pensato per i momenti in cui ti serve che la foto sia una forma diversa, un formato diverso o una dimensione diversa — e ti serve adesso, dal telefono che hai in mano.",
    ru: "Image Converter — это полноценный мобильный набор инструментов для работы с изображениями, который позволяет переработать фотографию прямо на iPhone, не выгружая её никуда и не создавая аккаунтов. Приложение выполняет конвертацию между форматами JPG, JPEG, PNG, WebP, BMP и TIFF и поддерживает пакетную обработку, благодаря чему целая папка снимков HEIC за один проход превращается в папку JPG, готовых для веба. Помимо конвертации форматов, в приложении есть компрессор, уменьшающий размер файла при заданном качестве и сохраняющий визуально незаметную разницу, инструмент изменения размера по пикселям или по длинной стороне для тех случаев, когда нужен точный контроль, обрезка с предустановленными соотношениями сторон для постов в соцсетях, поворот как отдельных снимков, так и больших пачек, а также инструмент склейки, объединяющий несколько фотографий в длинный скриншот или аккуратную сетку. Все инструменты работают локально: данные изображения не покидают iPhone, новый файл записывается сразу в вашу библиотеку, никакие промежуточные серверы не участвуют в процессе, а создавать аккаунт не нужно. Интерфейс доступен на 14 языках, основные инструменты конвертации бесплатны, а небольшая подписка Pro убирает рекламу и открывает максимальные размеры пакетов для тех, кто регулярно обрабатывает большие объёмы снимков. Image Converter создан для тех моментов, когда фотографию нужно сделать другой формы, другого формата или другого размера — и сделать это прямо сейчас, с iPhone в руке.",
    th: "Image Converter คือชุดเครื่องมือจัดการภาพบนมือถือที่ครบครัน สำหรับทุกคนที่ต้องการปรับแต่งภาพบนโทรศัพท์โดยไม่ต้องอัปโหลดที่ใด สามารถแปลงระหว่าง JPG, JPEG, PNG, WebP, BMP และ TIFF พร้อมรองรับการแปลงแบบแบตช์ ทำให้โฟลเดอร์ HEIC ทั้งโฟลเดอร์กลายเป็นโฟลเดอร์ JPG พร้อมใช้บนเว็บได้ในครั้งเดียว นอกเหนือจากการแปลงรูปแบบไฟล์ แอปยังมีเครื่องมือบีบอัดที่ลดขนาดไฟล์ตามคุณภาพที่เลือก เครื่องมือปรับขนาดตามพิกเซลหรือด้านที่ยาวที่สุด เครื่องมือครอบตัดพร้อมสัดส่วนสำเร็จรูปสำหรับโพสต์โซเชียล เครื่องมือหมุนภาพที่รองรับทั้งภาพเดี่ยวและแบบแบตช์ และเครื่องมือต่อภาพที่รวมหลายภาพเป็นภาพยาวหรือภาพตาราง ทุกเครื่องมือทำงานในเครื่อง ข้อมูลภาพไม่ออกจากโทรศัพท์ ไฟล์ใหม่จะถูกเขียนกลับเข้าคลังภาพโดยตรง และไม่ต้องสร้างบัญชี อินเทอร์เฟซรองรับ 14 ภาษา เครื่องมือแปลงหลักใช้งานได้ฟรี และการสมัครสมาชิก Pro เล็กๆ จะลบโฆษณาและปลดล็อกขนาดแบตช์ที่ใหญ่ที่สุด Image Converter ถูกสร้างมาเพื่อช่วงเวลาที่คุณต้องการให้ภาพอยู่ในรูปทรง รูปแบบ หรือขนาดอื่น และต้องการมันทันที บนโทรศัพท์ที่อยู่ในมือคุณค่ะ"
  },
  "money-tracker": {
    en: "Money Tracker is a privacy-first expense and income tracker for iPhone that keeps every entry on your device. The app is built around a single principle: the most personal number in your life is your bank balance, and that number does not need to live on someone else's server. The interface is a clean daily ledger with quick-entry for amount, category, and optional note; a swipe gesture marks an entry as paid or received, and a long press opens the edit sheet. A monthly view groups everything by category, a yearly view turns the year into a single sparkline, and a search box finds any entry by text, amount or tag. You can set monthly budgets by category and watch the ring fill as you spend; overspending is flagged the moment it happens rather than at the end of the month, so a single ring turning red is enough to course-correct before the next paycheck. Multi-currency support means a transfer from a foreign trip, a freelance invoice paid in dollars, and a local coffee in euros all land in the same ledger with the right base-currency conversion. Reports export to CSV for tax filing or backup, and the backup file is a plain JSON you can keep on iCloud Drive, Dropbox, or a USB stick — whichever you trust. Money Tracker supports fourteen languages, requires no account, shows no ads in its core flow, and keeps every number under your control. A small subscription unlocks unlimited budgets, custom categories, and cloud-style backup to your own storage. Recurring entries like rent, salary, or a monthly gym fee can be set up once and the app posts them on the right date every month, with a simple skip-this-month toggle for the times life does not follow the calendar; widgets for the home and lock screens put the current balance and the day's spend one tap away, so the most common question — 'what does my money look like right now?' — never needs more than a glance.",
    zh: "Money Tracker 是一款隐私优先的 iPhone 收支记账 App，每一笔记录都只保存在你自己的设备上。它的设计围绕一个核心理念：银行余额是你生活中最私密的数字，而这个数字没必要放在别人的服务器上。界面是一本清爽的日常流水账，金额、分类和备注都能快速录入；滑动一下就能把一笔标记为已付或已收，长按则打开编辑面板。月视图按分类汇总，年视图把一整年浓缩成一条走势曲线，搜索框支持按文字、金额或标签查找任意一笔记录。你可以为每个分类设置月度预算，看着圆环随消费一点点填满；超支时立刻提示，而不是等到月底才发现，圆环变红就是信号，让你在下个发薪日之前及时调整。多币种支持让出国旅行的转账、以美元结算的接单发票和用欧元买的咖啡，都能按正确的基准货币汇率汇入同一本账。报表可导出为 CSV，用于报税或备份，备份文件是标准的 JSON 格式，可以放在 iCloud Drive、Dropbox 或 U 盘里，存在哪里由你说了算。Money Tracker 支持 14 种语言，无需注册账号，核心流程不含广告，所有数字都掌握在你手中。小额订阅可解锁无限预算、自定义分类，以及备份到你自有存储空间的云端方案。房租、工资、健身房月费这类 Recurring 项目只需设置一次，App 每月都会在正确的日期自动入账，遇到计划赶不上变化时轻点“本月跳过”即可；桌面和锁屏 widget 让当前余额与今日花销触手可及，“我现在的钱还剩多少”这个最常被问到的问题，一眼就有答案。",
    "zh-TW": "Money Tracker 是一款重視隱私的 iPhone 記帳 App,所有收支紀錄都儲存在你的裝置上。整個 App 圍繞著一個核心原則打造:你生活中最私密的數字就是銀行餘額,而這個數字不需要存在別人的伺服器上。介面採用簡潔的每日帳本設計,快速輸入金額、類別與選填備註;滑動手勢即可標記款項已支付或入帳,長按則開啟編輯面板。月度檢視依類別彙整所有紀錄,年度檢視將整年化為單一走勢圖,搜尋框可依文字、金額或標籤找到任何一筆資料。你可以為各類別設定每月預算,並看著圓環隨著花費逐漸填滿;超支時即刻標記提醒,不用等到月底才發現,只要圓環轉紅,就能在下一次薪水入帳前即時調整。多幣別支援讓出國旅遊的匯款、美元計價的接案發票、歐元支付的本地咖啡,都能依正確的基礎貨幣換算後,匯入同一本帳。報表可匯出為 CSV 供報稅或備份使用,備份檔為標準 JSON 格式,可存放在 iCloud Drive、Dropbox 或 USB 隨身碟,選擇你最信任的儲存空間。Money Tracker 支援 14 種語言,無需註冊帳號,核心流程完全不顯示廣告,所有數字都由你掌控。小額訂閱可解鎖無限預算、自訂類別,以及個人儲存空間的雲端備份功能。租金、薪水或每月健身房月費等定期項目,只需設定一次,App 就會在正確日期自動入帳;若遇到突發狀況,只要輕按「略過本月」即可跳過。桌面與鎖定畫面的 Widget 小工具,讓你一抬手就能看到目前餘額與今日支出,最常被問的問題「我現在的財務狀況如何?」只需一眼就能回答。",
    ja: "Money Trackerは、すべての取引を端末内に保管する、プライバシーを最優先したiPhone向け収支管理アプリです。このアプリは1つの原則に基づいて作られています。人生の最も個人的な数字、それは銀行残高であり、その数字が他社のサーバーに置かれる必要はないという信念です。インターフェースはすっきりと整理された日次台帳で、金額、カテゴリ、任意のメモをすばやく入力できます。スワイプ操作で取引を支払い済みまたは受領済みにマークでき、長押しで編集シートが開きます。月別ビューではカテゴリごとにまとめて表示し、年別ビューでは1年間を1本のスパークラインで確認でき、検索ボックスではテキスト、金額、タグから任意の取引を見つけられます。カテゴリ別の月次予算を設定すれば、支出が増えるにつれてリングが満たされていきます。予算超過は月末ではなくその瞬間に通知されるため、リングが赤く変わるだけで、次の給料日前にも余裕を持って軌道修正できます。多通貨対応により、海外旅行での両替、ドル建てのフリーランス請求書、ユーロ建ての地元でのコーヒー代も、すべて適切な基準通貨換算で同じ台帳に記録されます。レポートはCSV形式でエクスポートでき、税務申告やバックアップにご利用いただけます。バックアップファイルはプレーンなJSON形式で、iCloud Drive、Dropbox、USBメモリなど、信頼できる任意の場所に保管できます。Money Trackerは14言語に対応し、アカウント不要で、基本画面には広告が表示されません。少額のサブスクリプションを契約すると、予算数の上限解除、カスタムカテゴリの追加、自分専用のストレージへのクラウド形式バックアップがご利用いただけます。家賃、給与、月会費などの定期取引は一度設定するだけで、毎月適切な日付に自動で記録されます。今月はスキップという簡単なトグルで、暦通りではない生活にも対応します。ホーム画面とロック画面用のウィジェットで、現在の残高と本日の支出を1タップで確認できるため、「今の家計はどうなっているか」という最もよくある疑問も、一目で答えられます。",
    ko: "Money Tracker는 모든 내역을 기기에만 보관하는 개인정보 보호 최우선 iPhone용 가계부입니다. 가장 개인적인 숫자는 통장 잔고라는 원칙 위에 만들어져 그 숫자가 남의 서버에 머물 이유가 없습니다. 일일 장부에서 금액, 카테고리, 메모를 빠르게 입력하고, 스와이프로 입금과 지출을 표시하며, 길게 누르면 편집 화면이 열립니다. 월간은 카테고리별, 연간은 스파크라인으로 정리되고 검색창에서 어떤 항목이든 바로 찾을 수 있습니다. 카테고리별 월간 예산을 설정하면 원형 게이지가 차오르고 초과 시 즉시 빨갛게 표시되어 다음 월급 전에 바로잡을 수 있습니다. 다중 통화로 해외 송금, 달러 청구, 유로 커피까지 한 장부에 자연스럽게 기록됩니다. 보고서는 CSV 내보내기로 세금 신고나 백업에 쓸 수 있고, 백업은 일반 JSON이라 iCloud Drive, Dropbox, USB 어디든 보관하실 수 있습니다. 14개 언어를 지원하며 계정도, 핵심 흐름의 광고도 없습니다. 소소한 구독으로 무제한 예산, 맞춤 카테고리, 클라우드 백업까지 열어 드립니다. 월세나 월급은 한 번 등록하면 매달 자동 기록되고, 홈 화면과 잠금 화면 위젯으로 잔고와 오늘의 지출을 탭 한 번으로 확인할 수 있습니다.",
    vi: "Money Tracker là ứng dụng theo dõi thu chi ưu tiên quyền riêng tư dành cho iPhone, lưu giữ mọi khoản mục ngay trên thiết bị của bạn. Ứng dụng được xây dựng xoay quanh một nguyên tắc: con số riêng tư nhất trong cuộc đời bạn chính là số dư tài khoản ngân hàng, và con số đó không cần phải nằm trên máy chủ của ai khác. Giao diện là một sổ nhật ký hằng ngày gọn gàng với ô nhập nhanh cho số tiền, hạng mục và ghi chú tuỳ chọn; cử chỉ vuốt sẽ đánh dấu khoản mục là đã trả hoặc đã nhận, và nhấn giữ sẽ mở bảng chỉnh sửa. Chế độ xem theo tháng gom mọi thứ theo hạng mục, chế độ xem theo năm biến cả năm thành một đường sparkline duy nhất, và ô tìm kiếm sẽ truy ra bất kỳ khoản mục nào theo văn bản, số tiền hoặc thẻ. Bạn có thể đặt ngân sách hằng tháng theo hạng mục và theo dõi vòng tròn lấp đầy khi bạn chi tiêu; chi vượt mức được báo hiệu ngay khi xảy ra chứ không phải cuối tháng, nên chỉ một vòng tròn chuyển sang đỏ là đủ để bạn điều chỉnh trước kỳ lương tiếp theo. Hỗ trợ đa tiền tệ đồng nghĩa với việc một khoản chuyển từ chuyến du lịch nước ngoài, một hóa đơn freelance thanh toán bằng đô la và một ly cà phê địa phương tính bằng euro đều nằm chung trong một sổ với đúng tỉ giá quy đổi sang tiền tệ cơ sở. Báo cáo được xuất ra CSV để khai thuế hoặc sao lưu, và tệp sao lưu là một tệp JSON thuần có thể giữ trên iCloud Drive, Dropbox hoặc USB — bất kỳ nơi nào bạn tin tưởng. Money Tracker hỗ trợ 14 ngôn ngữ, không yêu cầu tài khoản, không hiển thị quảng cáo trong luồng chính và giữ mọi con số dưới sự kiểm soát của bạn. Một gói đăng ký nhỏ sẽ mở khóa ngân sách không giới hạn, hạng mục tùy chỉnh và sao lưu dạng đám mây vào chính bộ nhớ của bạn. Các khoản mục định kỳ như tiền thuê nhà, lương hoặc phí phòng gym hằng tháng có thể được thiết lập một lần và ứng dụng sẽ tự ghi vào đúng ngày mỗi tháng, kèm nút bật tắt bỏ qua tháng này cho những lúc cuộc sống không đi theo lịch; tiện ích cho màn hình chính và màn hình khóa đặt số dư hiện tại và khoản chi trong ngày chỉ cách một cú chạm, nên câu hỏi thường gặp nhất — \"tiền của mình bây giờ trông thế nào?\" — không bao giờ cần hơn một cái liếc.",
    id: "Money Tracker adalah pelacak pengeluaran dan pemasukan untuk iPhone yang mengutamakan privasi, dengan menyimpan setiap entri langsung di perangkatmu sendiri tanpa melalui server. Seluruh aplikasi dibangun di atas satu prinsip sederhana namun penting: angka paling personal dalam hidupmu adalah saldo bankmu, dan angka itu tidak perlu hidup atau tersimpan di server milik orang lain. Antarmukanya berupa buku catatan harian yang bersih dan rapi, dengan entri cepat untuk jumlah, kategori, dan catatan opsional; gestur geser sederhana menandai sebuah entri sebagai dibayar atau diterima, dan tekan lama akan membuka sheet edit lengkap untuk mengubah atau menghapus transaksi. Tampilan bulanan mengelompokkan semua transaksi berdasarkan kategori, tampilan tahunan mengubah satu tahun penuh menjadi satu sparkline tunggal yang mudah dibaca sekilas, dan kotak pencarian menemukan entri apa pun berdasarkan teks, jumlah, maupun tag. Kamu bisa mengatur anggaran bulanan per kategori dan melihat cincin perlahan terisi saat kamu belanja sepanjang bulan; pemborosan ditandai begitu terjadi secara real-time, bukan baru ketahuan di akhir bulan, jadi cukup satu cincin yang berubah merah sudah cukup untuk mengingatkanmu agar mengoreksi arah pengeluaran sebelum gajian berikutnya tiba. Dukungan multi-mata uang berarti transfer dari perjalanan ke luar negeri, invoice freelance dalam dolar, dan secangkir kopi lokal dalam euro semuanya masuk ke buku catatan yang sama dengan konversi otomatis ke mata uang dasar yang kamu pilih. Laporan keuangan bisa diekspor ke CSV untuk pelaporan pajak atau cadangan, dan file cadangannya berupa JSON polos yang bisa kamu simpan di iCloud Drive, Dropbox, atau stik USB. Money Tracker mendukung 14 bahasa, tidak butuh akun, tidak menampilkan iklan di alur utamanya, dan menjaga setiap angka keuanganmu tetap di bawah kendalimu. Langganan kecil membuka fitur anggaran tanpa batas, kategori kustom, dan backup gaya cloud ke penyimpanan pilihanmu sendiri. Entri berulang seperti biaya sewa, gaji bulanan, atau iuran gym cukup diatur sekali saja, dan aplikasinya akan mempostingnya secara otomatis di tanggal yang tepat setiap bulan, lengkap dengan toggle lewati-bulan-ini untuk saat hidup tidak mengikuti kalender; widget untuk layar utama dan layar kunci menampilkan saldo saat ini dan pengeluaran hari ini dalam satu ketukan, jadi pertanyaan paling umum — 'uangku sekarang gimana?' — tidak pernah butuh lebih dari satu pandang sekilas.",
    ar: "تطبيق Money Tracker هو متتبّع للمصروفات والدخل يضع الخصوصية في المقام الأول على iPhone، ويحفظ كل قيد على جهازك. بُني التطبيق حول مبدأ واحد: أكثر رقم شخصي في حياتك هو رصيد حسابك المصرفي، ولا حاجة لهذا الرقم أن يعيش على خادم شخص آخر. الواجهة عبارة عن دفتر يومي نظيف مع إدخال سريع للمبلغ والفئة وملاحظة اختيارية؛ وتُستخدم إيماءة السحب لتعليم القيد كمدفوع أو مُستلم، بينما تفتح ضغطة طويلة ورقة التعديل لتغيير أي تفصيل. تجمع العرض الشهري كل شيء حسب الفئة، ويحوّل العرض السنوي السنة بأكملها إلى خط بياني واحد، ويجد مربع البحث أي قيد بالنص أو المبلغ أو الوسم في لمح البصر. يمكنك تحديد ميزانيات شهرية حسب الفئة ومراقبة الدائرة وهي تمتليء كلما أنفقت؛ ويُعلَّم تجاوز الميزانية فور حدوثه بدلًا من نهاية الشهر، فمجرد أن تتحول الدائرة إلى اللون الأحمر يمكنك تصحيح المسار قبل الراتب التالي. يدعم التطبيق عدة عملات، فمثلًا تحويل من رحلة خارجية، أو فاتورة مستقل مدفوعة بالدولار، أو قهوة محلية باليورو كلها تصل إلى نفس الدفتر بتحويل صحيح للعملة الأساسية. تُصدَّر التقارير بصيغة CSV للإقرارات الضريبية أو النسخ الاحتياطي، وملف النسخ هو ملف JSON بسيط يمكنك الاحتفاظ به في iCloud Drive أو Dropbox أو USB — أيًا ما تثق به. يدعم Money Tracker ١٤ لغة، ولا يتطلب أي حساب، ولا يعرض إعلانات في تدفقه الأساسي، ويحافظ على كل رقم تحت سيطرتك الكاملة. اشتراك صغير يفتح ميزانيات غير محدودة، وفئات مخصّصة، ونسخًا احتياطيًا سحابيًا إلى تخزينك الخاص. يمكن إعداد القيود المتكررة مثل الإيجار أو الراتب أو رسوم النادي الشهرية مرة واحدة، وينشرها التطبيق في التاريخ الصحيح كل شهر، مع زر بسيط لتخطّي الشهر حين لا تسير الحياة وفق التقويم؛ وتضع أدوات الشاشة الرئيسية وشاشة القفل الرصيد الحالي وإنفاق اليوم بنقرة واحدة، فلا يحتاج السؤال الأكثر تكرارًا — \"كيف تبدو أموالي الآن؟\" — إلى أكثر من نظرة سريعة.",
    fr: "Money Tracker est un suivi de dépenses et de revenus privilégiant la confidentialité, pour iPhone, qui conserve chaque saisie sur votre appareil. L'application repose sur un principe unique : le chiffre le plus personnel de votre vie est votre solde bancaire, et ce chiffre n'a pas besoin de vivre sur le serveur de quelqu'un d'autre. L'interface est un journal quotidien épuré, avec une saisie rapide pour le montant, la catégorie et une note facultative ; un geste de balayage marque une entrée comme payée ou reçue, et un appui long ouvre la fiche d'édition. Une vue mensuelle regroupe tout par catégorie, une vue annuelle condense l'année en une seule courbe sparkline, et une zone de recherche retrouve n'importe quelle saisie par texte, montant ou étiquette. Vous pouvez définir des budgets mensuels par catégorie et regarder l'anneau se remplir au fil de vos dépenses ; le dépassement est signalé dès qu'il survient, et non à la fin du mois, de sorte qu'un simple anneau qui passe au rouge suffit pour rectifier le tir avant la prochaine paie. La prise en charge multi-devises signifie qu'un virement d'un voyage à l'étranger, une facture freelance payée en dollars et un café local en euros se retrouvent dans le même journal avec la bonne conversion vers la devise de référence. Les rapports s'exportent en CSV pour la déclaration fiscale ou la sauvegarde, et le fichier de sauvegarde est un JSON brut que vous pouvez conserver sur iCloud Drive, Dropbox ou une clé USB — celui en qui vous avez confiance. Money Tracker prend en charge 14 langues, ne nécessite aucun compte, n'affiche aucune publicité dans son flux principal, et garde chaque chiffre sous votre contrôle. Un petit abonnement débloque un nombre illimité de budgets, des catégories personnalisées et une sauvegarde de type cloud vers votre propre espace de stockage. Les écritures récurrentes comme le loyer, le salaire ou un abonnement mensuel à une salle de sport peuvent être configurées une seule fois, et l'application les inscrit à la bonne date chaque mois, avec une simple option « passer ce mois-ci » pour les fois où la vie ne suit pas le calendrier ; des widgets pour l'écran d'accueil et l'écran de verrouillage affichent le solde actuel et la dépense du jour d'un simple appui, de sorte que la question la plus fréquente — « à quoi ressemble mon argent en ce moment ? » — n'exige jamais plus qu'un coup d'œil.",
    de: "Money Tracker ist ein konsequent auf Datenschutz ausgerichteter Ausgaben- und Einnahmen-Tracker für das iPhone, der jeden einzelnen Eintrag ausschließlich auf Ihrem Gerät speichert. Die App folgt einem einzigen, klaren Grundsatz: Die persönlichste Zahl in Ihrem Leben ist Ihr Kontostand – und diese Zahl muss nicht auf dem Server eines anderen liegen, wo sie in Profilen verarbeitet und für Werbung ausgewertet wird. Die Oberfläche ist ein sauberes, aufgeräumtes Tagesjournal mit Schnelleingabe für Betrag, Kategorie und optionale Notiz; eine sanfte Wisch-Geste markiert einen Eintrag als bezahlt oder erhalten, ein langes Drücken öffnet die vertraute Bearbeitungsmaske. Eine Monatsansicht gruppiert alles nach Kategorien und zeigt auf einen Blick, wohin das Geld fließt, eine Jahresansicht verdichtet das gesamte Jahr zu einer einzigen aussagekräftigen Verlaufslinie, und ein leistungsfähiges Suchfeld findet jeden noch so alten Eintrag nach Textfragment, Betrag oder Schlagwort in Sekunden. Sie können monatliche Budgets nach Kategorie festlegen und live zusehen, wie sich der Ring beim Ausgaben füllt; Überschreitungen werden sofort markiert, nicht erst am Monatsende – ein einziger rot werdender Ring genügt, um gegenzusteuern, bevor das nächste Gehalt eintrifft. Die Mehrwährungs-Unterstützung sorgt dafür, dass eine Überweisung aus dem Auslandsurlaub, eine Freelance-Rechnung in Dollar und ein lokal bezahlter Café-Espresso in Euro gemeinsam im Journal mit korrekter Umrechnung in die frei wählbare Basiswährung landen. Berichte exportieren Sie als CSV für die Steuererklärung oder als Backup; die Sicherungsdatei ist ein einfaches, lesbares JSON, das Sie in iCloud Drive, Dropbox oder auf einem USB-Stick ablegen können – ganz nach Ihrem Vertrauen. Money Tracker unterstützt 14 Sprachen, benötigt keinerlei Konto, zeigt im Kernfluss keine Werbung und behält jede einzelne Zahl komplett in Ihrer Hand. Ein kleines Abonnement schaltet unbegrenzte Budgets, eigene Kategorien und Cloud-Backups in Ihren eigenen Speicher frei. Wiederkehrende Einträge wie Miete, Gehalt oder die monatliche Fitnessstudio-Gebühr richten Sie einmal ein, und die App bucht sie jeden Monat automatisch am richtigen Datum – mit einer einfachen Option, um einen Monat zu überspringen, wenn das Leben einmal nicht dem Kalender folgt. Widgets für den Startbildschirm und Sperrbildschirm zeigen den aktuellen Saldo und die heutigen Ausgaben mit einem einzigen Tipp; so beantwortet sich die häufigste Frage im Alltag – „Wie sieht mein Geld gerade aus?“ – endlich mit einem einzigen, ruhigen Blick.",
    es: "Money Tracker es un gestor de gastos e ingresos para iPhone que prioriza tu privacidad y guarda cada entrada en tu dispositivo. La app se construye sobre un único principio: el número más personal de tu vida es tu saldo bancario, y ese número no necesita vivir en el servidor de nadie. La interfaz es un libro diario limpio con entrada rápida de importe, categoría y nota opcional; un gesto de deslizar marca una entrada como pagada o recibida, y una pulsación larga abre la hoja de edición para corregirla. Una vista mensual agrupa los datos por categoría, una vista anual convierte el año en una sola línea de tendencia, y un buscador encuentra cualquier entrada por texto, importe o etiqueta. Puedes fijar presupuestos mensuales por categoría y ver cómo se va llenando el anillo al gastar; cuando te pasas, se señala al instante en lugar de avisarte a fin de mes, así que basta con ver un anillo rojo para corregir el rumbo antes del próximo cobro. El soporte multimoneda significa que una transferencia de un viaje al extranjero, una factura freelance cobada en dólares y un café pagado en euros caen en el mismo libro mayor con la conversión correcta a tu moneda base. Los informes se exportan a CSV para declarar impuestos o como copia de seguridad, y el archivo de respaldo es un JSON plano que puedes guardar en iCloud Drive, Dropbox o una memoria USB, donde tú confíes. Money Tracker está disponible en 14 idiomas, no requiere cuenta, no muestra anúncios en su flujo principal y mantiene cada número bajo tu control. Una pequeña suscripción desbloquea presupuestos sin límite, categorías personalizadas y copias de seguridad en tu propio almacenamiento. Las entradas recurrentes como el alquiler, el sueldo o la cuota mensual del gimnasio se configuran una vez y la app las registra el día correcto cada mes, con un simple interruptor para saltarse un mes cuando la vida no sigue el calendario; los widgets para la pantalla de inicio y la pantalla de bloqueo ponen el saldo actual y el gasto del día a un toque, de modo que la pregunta más frecuente — ¿cómo está mi dinero ahora mismo? — nunca necesita más que una mirada.",
    pt: "O Money Tracker é um aplicativo de controle de gastos e receitas para iPhone que prioriza a privacidade e mantém cada registro no seu dispositivo. Ele foi construído em torno de um único princípio: o número mais pessoal da sua vida é o saldo da sua conta, e esse número não precisa ficar guardado no servidor de ninguém. A interface é um livro-caixa diário limpo, com entrada rápida para valor, categoria e nota opcional; um gesto de deslize marca uma entrada como paga ou recebida, e um toque longo abre a tela de edição para corrigir qualquer detalhe. Uma visão mensal agrupa tudo por categoria, uma visão anual transforma o ano em um único gráfico de linha, e uma caixa de busca encontra qualquer entrada por texto, valor ou etiqueta. Você pode definir orçamentos mensais por categoria e acompanhar o anel se preencher conforme você gasta; o estouro do orçamento é sinalizado no momento em que acontece, e não no fim do mês — basta um anel ficar vermelho para você corrigir o rumo antes do próximo pagamento. O suporte a várias moedas faz com que uma transferência de uma viagem ao exterior, uma cobrança de freelance paga em dólares e um café local em euros caiam todos no mesmo livro-caixa, com a conversão correta para a moeda de base que você escolheu. Os relatórios são exportados em CSV para declaração de imposto de renda ou backup, e o arquivo de backup é um JSON simples que você pode guardar no iCloud Drive, Dropbox ou em um pen drive USB — onde você preferir e confiar. O Money Tracker oferece suporte a 14 idiomas, não exige conta, não mostra anúncios no fluxo principal e mantém cada número sob seu controle. Uma assinatura pequena libera orçamentos ilimitados, categorias personalizadas e backup no seu próprio armazenamento. Lançamentos recorrentes como aluguel, salário ou mensalidade da academia podem ser configurados uma vez, e o app registra tudo na data certa todo mês, com uma opção simples para pular um mês quando a vida não segue o calendário; widgets para a tela inicial e a tela de bloqueio colocam o saldo atual e os gastos do dia a um toque de distância, para que a pergunta mais comum — 'como está meu dinheiro agora?' — nunca precise de mais do que uma olhada rápida.",
    it: "Money Tracker è un tracker di spese ed entrate per iPhone che mette la privacy al primo posto e tiene ogni registrazione sul tuo dispositivo. L'app ruota attorno a un unico principio: il numero più personale della tua vita è il saldo del conto in banca, e quel numero non ha bisogno di vivere sul server di qualcun altro. L'interfaccia è un registro quotidiano pulito con inserimento rapido per importo, categoria e nota opzionale; un gesto di scorrimento segna una registrazione come pagata o ricevuta, e una pressione lunga apre la scheda di modifica. Una vista mensile raggruppa tutto per categoria, una vista annuale trasforma l'anno in una singola sparkline, e una casella di ricerca trova qualsiasi registrazione per testo, importo o tag. Puoi impostare budget mensili per categoria e guardare l'anello che si riempie mentre spendi; lo sforamento del budget viene segnalato nel momento in cui accade e non alla fine del mese, così un solo anello che diventa rosso basta per correggere la rotta prima dello stipendio successivo. Il supporto multi-valuta fa sì che un bonifico da un viaggio all'estero, una fattura da freelancer pagata in dollari e un caffè locale in euro finiscano tutti nello stesso registro con la giusta conversione nella valuta di base. I report si esportano in CSV per la dichiarazione dei redditi o come backup, e il file di backup è un semplice JSON che puoi conservare su iCloud Drive, Dropbox o una chiavetta USB — quello di cui ti fidi di più. Money Tracker supporta quattordici lingue, non richiede account, non mostra pubblicità nel flusso principale, e tiene ogni numero sotto il tuo controllo. Un piccolo abbonamento sblocca budget illimitati, categorie personalizzate e backup in stile cloud sul tuo spazio personale. Le registrazioni ricorrenti come affitto, stipendio o quota mensile della palestra si impostano una volta sola e l'app le registra nella data giusta ogni mese, con un semplice pulsante «salta questo mese» per quando la vita non segue il calendario; i widget per la schermata home e di blocco mostrano il saldo attuale e la spesa del giorno a un tocco di distanza, così la domanda più frequente — «quanto ho in questo momento?» — non ha mai bisogno di più di un'occhiata.",
    ru: "Money Tracker — это ориентированный на приватность трекер расходов и доходов для iPhone, который хранит каждую запись на вашем устройстве. В основе приложения лежит простой принцип: самая личная цифра в вашей жизни — это состояние вашего счёта, и этой цифре не место на чужом сервере. Интерфейс — это аккуратная ежедневная книга с быстрым вводом суммы, категории и необязательного комментария; свайп помечает запись как оплаченную или полученную, а долгое нажатие открывает окно редактирования. Месячный вид группирует всё по категориям, годовой превращает год в единую искру-кривую, а строка поиска находит любую запись по тексту, сумме или тегу. Можно задать месячные бюджеты по категориям и следить, как заполняется кольцо по мере расходов; перерасход подсвечивается в момент, когда он происходит, а не в конце месяца — достаточно одного красного кольца, чтобы скорректировать курс до следующей зарплаты. Поддержка нескольких валют означает, что перевод из зарубежной поездки, оплаченный в долларах фрилансерский инвойс и местный кофе в евро попадают в одну ведомость с правильным приведением к базовой валюте. Отчёты экспортируются в CSV для налоговой или резервной копии, а файл резервной копии — это обычный JSON, который можно хранить в iCloud Drive, Dropbox или на USB-накопителе — там, где вы ему доверяете. Money Tracker поддерживает 14 языков, не требует аккаунта, не показывает рекламу в основном сценарии и держит каждую цифру под вашим контролем. Небольшая подписка открывает неограниченные бюджеты, пользовательские категории и облачное резервное копирование в ваше собственное хранилище. Регулярные записи — аренда, зарплата, абонемент в спортзал — настраиваются один раз, и приложение само вносит их нужного числа каждого месяца, с простым переключателем «пропустить этот месяц» для случаев, когда жизнь не следует календарю; виджеты для главного экрана и экрана блокировки выводят текущий баланс и сегодняшние траты в одно нажатие, так что самый частый вопрос — «сколько у меня сейчас денег?» — никогда не требует больше одного взгляда.",
    th: "Money Tracker คือแอปบันทึกรายรับรายจ่ายที่ให้ความสำคัญกับความเป็นส่วนตัวเป็นอันดับแรกสำหรับ iPhone ที่เก็บทุกรายการไว้บนอุปกรณ์ของคุณ แอปนี้สร้างขึ้นบนหลักการเดียว: ตัวเลขที่เป็นส่วนตัวที่สุดในชีวิตของคุณคือยอดเงินในบัญชีธนาคาร และตัวเลขนั้นไม่จำเป็นต้องไปอยู่บนเซิร์ฟเวอร์ของใคร อินเทอร์เฟซเป็นบัญชีรายวันที่สะอาดตาพร้อมช่องกรอกด่วนสำหรับจำนวนเงิน หมวดหมู่ และบันทึกเสริม ท่าทางการปัดจะทำเครื่องหมายรายการว่าจ่ายหรือได้รับ ส่วนการกดค้างจะเปิดหน้าต่างแก้ไข มุมมองรายเดือนจัดกลุ่มทุกอย่างตามหมวดหมู่ มุมมองรายปีเปลี่ยนปีทั้งปีเป็นสปาร์กไลน์เส้นเดียว และช่องค้นหาจะค้นหารายการใดก็ได้จากข้อความ จำนวนเงิน หรือแท็ก คุณสามารถตั้งงบประมาณรายเดือนตามหมวดหมู่และดูวงแหวนเติมเต็มเมื่อคุณใช้จ่าย การใช้จ่ายเกินจะถูกแจ้งเตือนทันทีที่เกิดขึ้น ไม่ใช่ปลายเดือน ดังนั้นวงแหวนเปลี่ยนเป็นสีแดงเพียงวงเดียวก็เพียงพอที่จะปรับเปลี่ยนพฤติกรรมก่อนเช็คเงินเดือนฉบับถัดไป รองรับหลายสกุลเงิน หมายความว่าการโอนจากทริปต่างประเทศ ใบแจ้งหนี้ฟรีแลนซ์ที่จ่ายเป็นดอลลาร์ และกาแฟท้องถิ่นเป็นยูโร ทั้งหมดลงในบัญชีเดียวกันพร้อมการแปลงสกุลเงินฐานที่ถูกต้อง รายงานส่งออกเป็น CSV สำหรับยื่นภาษีหรือสำรองข้อมูล และไฟล์สำรองเป็น JSON ธรรมดาที่คุณเก็บใน iCloud Drive, Dropbox หรือ USB ได้ตามที่คุณไว้วางใจ Money Tracker รองรับ 14 ภาษา ไม่ต้องสร้างบัญชี ไม่มีโฆษณาในการใช้งานหลัก และเก็บทุกตัวเลขไว้ภายใต้การควบคุมของคุณ การสมัครสมาชิกเล็กๆ จะปลดล็อกงบประมาณไม่จำกัด หมวดหมู่ที่กำหนดเอง และการสำรองข้อมูลแบบคลาวด์ไปยังที่เก็บข้อมูลของคุณเอง รายการประจำเช่นค่าเช่า เงินเดือน หรือค่ายิมรายเดือนสามารถตั้งค่าได้ครั้งเดียว แล้วแอปจะบันทึกในวันที่ถูกต้องทุกเดือน พร้อมปุ่มข้ามเดือนนี้สำหรับช่วงที่ชีวิตไม่เป็นไปตามปฏิทิน วิดเจ็ตสำหรับหน้าจอหลักและหน้าจอล็อกทำให้ยอดเงินปัจจุบันและยอดใช้จ่ายของวันอยู่ห่างจากการแตะเพียงครั้งเดียว ดังนั้นคำถามที่พบบ่อยที่สุด ตอนนี้เงินของฉันเป็นอย่างไร จึงไม่จำเป็นต้องมองมากกว่าแค่ชำเลยค่ะ"
  },
  "cleanphoto": {
    en: "CleanPhoto is a free iOS photo cleaner that runs entirely on your phone, with no account required and no photo ever uploaded to any server. The app is designed to do one job well: help you reclaim space in a library that quietly fills up with duplicates, near-identical burst sets, old screenshots, and videos you recorded once and never re-watched. Three local scans do the heavy lifting: exact-duplicate detection groups photos with identical dimensions captured in the same second, burst detection chains together photos taken within ten seconds of each other, and screenshot detection pulls captures from the dedicated album on iOS or scans file names on Android. Each scan produces reviewable groups where the largest file is presented as the keeper, so the decision becomes a glance rather than a comparison. Beyond cleanup, the app includes a month-by-month swipe review for everything the scans do not catch, an image compressor that shrinks the files you want to keep without visible quality loss, a big-files view that surfaces the heaviest items first, and a duplicate-contacts cleaner that tidies the address book alongside the library. Every deletion goes through the system photo library with your explicit confirmation. Pro removes ads; free users watch one short ad per deletion batch.",
    zh: "CleanPhoto 是一款免费的 iOS 照片清理 App，全部处理都在你的手机本地完成，无需注册账号，照片也绝不会上传到任何服务器。它只专注做好一件事：帮你从被悄悄塞满的相册里，清理掉重复照片、几乎一模一样的连拍、过期截图，以及那些录完就再没看过的视频，把宝贵的存储空间重新腾出来。三项本地扫描承担了最重的活儿：完全重复检测会把同一秒拍摄、尺寸完全相同的照片归为一组；连拍检测会把十秒内连续拍摄的照片串在一起；截图检测则会从 iOS 的专用相册中提取截图，在 Android 上则通过文件名识别。每次扫描都会生成可供逐组查看的结果，并自动把体积最大的那张标为建议保留，于是决策从反复比对变成了扫一眼就定。除了清理，App 还提供按月份滑动回顾的模式，用来处理扫描没能覆盖到的照片；图片压缩工具能在肉眼看不出画质损失的前提下，为你想留下的照片瘦身；大文件视图会优先列出最占空间的项目；重复联系人清理工具则能在整理相册的同时，顺手把通讯录也理清楚。每一次删除都通过系统相册执行，并需要你明确确认。Pro 可去除广告；免费用户每批删除只需观看一条短广告。",
    "zh-TW": "CleanPhoto 是一款免費的 iOS 照片清理 App,完全在你的手機上運作,無需註冊帳號,照片絕不上傳到任何伺服器。App 專注做好一件事:幫你從默默塞滿的圖庫中,清出那些重複照片、相似連拍、舊截圖,以及錄了卻再也沒看過的影片,重新取回寶貴的儲存空間。三項本機掃描承擔所有重任:完全重複偵測會將同一秒拍攝、尺寸相同的照片分組;連拍偵測會將十秒內連續拍攝的照片串連起來;截圖偵測則從 iOS 專用相簿擷取截圖,或在 Android 上掃描檔案名稱。每次掃描都會產生可供檢視的群組,並自動把容量最大的檔案標示為建議保留檔,讓決策從逐一比對變成一眼判斷。除了清理功能,App 還提供按月分類的滑動檢視模式,讓你處理掃描漏網的照片;圖片壓縮器能在不犧牲視覺品質的前提下,縮小你想保留的檔案;大型檔案檢視優先列出最肥大的項目;重複聯絡人清理工具則能在整理圖庫的同時,順便整頓通訊錄。每一次刪除都會透過系統照片圖庫執行,並經過你的明確確認。Pro 版可去除廣告;免費使用者每次刪除批次只需觀看一支短廣告。",
    ja: "CleanPhotoは、スマートフォン上ですべて完結する無料の写真整理アプリです。アカウント登録は不要で、写真がサーバーにアップロードされることは一切ありません。このアプリが担う仕事は1つだけ。それは、知らぬ間に重複写真や似た構図の連写、古いスクリーンショット、一度録画して二度と再生していない動画で埋まっていく写真ライブラリから、容量を取り戻すお手伝いです。3つのローカルスキャンがその作業を担います。完全重複検出は同じ秒間に撮影された同一サイズの写真をまとめ、連写検出は10秒以内に撮影された写真を連鎖し、スクリーンショット検出はiOSの専用アルバムから、またはAndroidではファイル名から抽出します。各スキャンはレビュー可能なグループを生成し、ファイルサイズが最大の写真が推奨保存候補として表示されるため、比較ではなく一目見るだけで判断できます。整理機能に加え、スキャンでは拾いきれない月単位のスワイプレビュー機能、保存したい写真を視覚的な劣化なしに縮小する画像圧縮機能、サイズの大きなファイルから順に表示する大容量ファイルビュー機能、ライブラリと一緒にアドレス帳も整理できる重複連絡先クリーンアップ機能も搭載しています。削除はすべて、写真ライブラリを通じて、ユーザーの明示的な確認のもとで実行されます。Proユーザーは広告が表示されず、無料ユーザーは削除バッチごとに短い広告を1回視聴します。",
    ko: "CleanPhoto는 계정도, 서버 전송도 없는 무료 iOS 사진 정리 앱입니다. 중복 사진, 비슷한 연사 묶음, 다시 보지 않을 스크린샷과 영상으로 가득 찬 보관함의 공간을 되찾는 데 집중했습니다. 세 가지 로컬 스캔이 무거운 작업을 처리합니다. 같은 순간 동일 크기로 찍힌 사진을 묶는 완전 중복 감지, 10초 이내 연속 촬영을 잇는 연사 감지, 전용 앨범에서 추출하거나 파일명을 분석하는 스크린샷 감지가 그것입니다. 각 결과는 검토 가능한 묶음으로 정리되고 가장 큰 파일이 대표로 제시되어 비교 없이 한눈에 결정할 수 있습니다. 스캔에서 빠진 사진은 월 단위 스와이프 검토로 확인하고, 남길 사진의 크기를肉眼으로 티 나지 않게 줄여 주는 압축, 용량 큰 항목부터 보여 주는 대용량 보기, 사진 정리와 함께하는 중복 연락처 정리 기능도 제공합니다. 모든 삭제는 사용자 확인을 거쳐 시스템 보관함을 통해 진행되며, Pro는 광고를 제거하고 무료 사용자는 묶음당 짧은 광고 한 번을 시청합니다.",
    vi: "CleanPhoto là ứng dụng dọn dẹp ảnh miễn phí trên iOS chạy hoàn toàn trên điện thoại của bạn, không yêu cầu tài khoản và không bao giờ tải ảnh lên bất kỳ máy chủ nào. Ứng dụng được thiết kế để làm tốt một việc: giúp bạn lấy lại dung lượng trong thư viện ảnh đang âm thầm đầy dần bởi các ảnh trùng lặp, những bộ chụp liên tiếp gần giống nhau, ảnh chụp màn hình cũ và những video bạn quay một lần rồi không bao giờ xem lại. Ba lần quét cục bộ đảm nhận phần việc nặng: phát hiện trùng lặp chính xác gom các ảnh có cùng kích thước chụp trong cùng một giây, phát hiện chụp liên tiếp nối chuỗi ảnh chụp trong vòng mười giây với nhau, và phát hiện ảnh chụp màn hình trích ảnh từ album chuyên dụng trên iOS hoặc quét theo tên tệp trên Android. Mỗi lần quét tạo ra các nhóm có thể xem lại, trong đó tệp lớn nhất được đề xuất làm ảnh giữ lại, nên quyết định trở thành một cái liếc chứ không phải một sự so sánh. Ngoài việc dọn dẹp, ứng dụng còn có chế độ xem lại theo tháng với thao tác vuốt cho mọi thứ mà quét không bắt được, công cụ nén hình ảnh thu nhỏ tệp bạn muốn giữ mà không mất chất lượng nhìn thấy được, chế độ xem tệp lớn đưa các mục nặng nhất lên đầu, và trình dọn danh bạ trùng lặp giúp gọn gàng sổ địa chỉ cùng với thư viện. Mọi lần xóa đều đi qua thư viện ảnh hệ thống với sự xác nhận rõ ràng của bạn. Pro sẽ xóa quảng cáo; người dùng miễn phí xem một quảng cáo ngắn cho mỗi lô xóa.",
    id: "CleanPhoto adalah pembersih foto iOS gratis yang berjalan sepenuhnya di HP, tanpa perlu bikin akun, dan tanpa satu pun foto yang pernah diunggah ke server mana pun. Aplikasi ini dirancang secara khusus untuk melakukan satu tugas dengan sangat baik: membantu kamu merebut kembali ruang penyimpanan di perpustakaan foto yang pelan-pelan tapi pasti dipenuhi oleh foto-foto duplikat yang tidak kamu sadari, rangkaian burst yang nyaris identik dari kamera iPhone, screenshot lama yang sudah tidak relevan dengan kehidupanmu saat ini, dan video-video pendek yang direkam sekali tapi ternyata tidak pernah ditonton ulang sama sekali. Tiga jenis pemindaian lokal di dalam aplikasi ini melakukan sebagian besar pekerjaan berat secara otomatis: deteksi duplikat persis akan mengelompokkan foto-foto dengan dimensi dan ukuran file yang identik dan diambil di detik yang sama persis, deteksi burst merantai bersama foto-foto yang diambil dalam rentang waktu sepuluh detik satu sama lain, dan deteksi screenshot secara otomatis menarik semua tangkapan layar dari album khusus di iOS atau memindai pola nama file di Android. Setiap pemindaian menghasilkan grup-grup yang bisa kamu tinjau dengan mudah, di mana file dengan ukuran terbesar otomatis ditampilkan sebagai kandidat utama yang akan dipertahankan, sehingga keputusan yang harus kamu buat jadi cukup sekilas pandang alih-alih perbandingan manual yang melelahkan dan membuang waktu. Di luar fitur pembersihan utama, aplikasinya juga mencakup tinjauan geser bulan-per-bulan untuk semua foto yang tidak berhasil tertangkap oleh pemindaian otomatis, kompresor gambar yang memperkecil ukuran file dari foto yang ingin tetap kamu simpan tanpa kehilangan kualitas yang terlihat oleh mata, tampilan file besar yang memunculkan item-item terberat lebih dulu agar kamu tahu mana yang paling banyak menghabiskan ruang, dan pembersih kontak duplikat yang merapikan buku alamat di samping perpustakaan foto dalam satu aplikasi terpadu. Setiap tindakan penghapusan foto melewati perpustakaan foto sistem dengan konfirmasi eksplisit darimu terlebih dahulu, jadi tidak ada yang akan terhapus secara diam-diam tanpa persetujuan. Versi Pro menghilangkan iklan sepenuhnya dari pengalaman penggunaan; sementara itu, pengguna gratis cukup menonton satu iklan pendek per batch penghapusan sebagai gantinya.",
    ar: "تطبيق CleanPhoto هو منظّف صور مجاني على iOS يعمل بالكامل على هاتفك، دون الحاجة إلى حساب ودون رفع أي صورة إلى أي خادم. صُمم التطبيق ليؤدي مهمة واحدة بإتقان: مساعدتك على استعادة المساحة في مكتبة تمتليء بهدوء بالصور المكررة، ومجموعات اللقطات المتتالية شبه المتطابقة، ولقطات الشاشة القديمة، ومقاطع الفيديو التي سجّلتها مرة ولم تعُد تشاهدها. تقوم ثلاث عمليات فحص محلية بالجهد الأكبر: اكتشاف التطابق التام يجمع الصور ذات الأبعاد نفسها الملتقطة في الثانية نفسها، واكتشاف اللقطات المتتالية يربط الصور الملتقطة خلال ١٠ ثوانٍ من بعضها البعض في سلسلة واحدة، واكتشاف لقطات الشاشة يسحب الصور من الألبوم المخصص في iOS أو يفحص أسماء الملفات على Android. ينتج عن كل فحص مجموعات قابلة للمراجعة، تُعرَض فيها أكبر ملف كصورة محتفظ بها تلقائيًا، ليصبح القرار نظرة لا مقارنة متعبة. إلى جانب التنظيف، يتضمّن التطبيق مراجعة شهرية بالسحب لكل ما لم تلتقطه عمليات الفحص، وضاغط صور يصغّر الملفات التي تريد الاحتفاظ بها دون فقدان ملحوظ في الجودة، وعرضًا للملفات الكبيرة يبرز الأثقل منها أولًا لتبدأ به، ومنظّف جهات اتصال مكررة يرتّب دفتر العناوين إلى جانب المكتبة. كل عملية حذف تمر عبر مكتبة الصور في النظام بتأكيد صريح منك حتى لا تضيع صورة مهمة. تزيل Pro الإعلانات؛ أما المستخدمون المجانيون فيشاهدون إعلانًا قصيرًا واحدًا لكل دفعة حذف.",
    fr: "CleanPhoto est un nettoyeur de photos iOS gratuit qui s'exécute entièrement sur votre téléphone, sans compte requis et sans aucune photo téléversée sur un serveur. L'application est conçue pour accomplir une seule mission avec efficacité : vous aider à récupérer de l'espace dans une bibliothèque qui se remplit en silence de doublons, de séries de prises de vue quasi identiques, de vieilles captures d'écran et de vidéos que vous avez enregistrées une fois sans jamais les revisionner. Trois analyses locales font le gros du travail : la détection des doublons exacts regroupe les photos de dimensions identiques capturées à la même seconde, la détection des rafales enchaîne les photos prises à moins de dix secondes d'intervalle, et la détection des captures d'écran extrait les prises depuis l'album dédié sur iOS ou analyse les noms de fichiers sur Android. Chaque analyse produit des groupes à examiner où la photo la plus volumineuse est présentée comme celle à conserver, de sorte que la décision se prend d'un coup d'œil plutôt qu'à coups de comparaison. Au-delà du nettoyage, l'application inclut une revue mensuelle par balayage pour tout ce que les analyses n'ont pas attrapé, un compresseur d'images qui réduit la taille des fichiers que vous souhaitez conserver sans perte visible de qualité, une vue des fichiers volumineux qui fait remonter en premier les éléments les plus lourds, et un nettoyeur de contacts en double qui fait le ménage dans le carnet d'adresses en parallèle de la bibliothèque. Chaque suppression passe par la photothèque du système avec votre confirmation explicite. Pro supprime les publicités ; les utilisateurs gratuits regardent une courte publicité par lot de suppression.",
    de: "CleanPhoto ist ein kostenloser iOS-Fotoaufräumer, der vollständig auf Ihrem iPhone läuft – ohne Konto, ohne Anmeldung und ohne dass auch nur ein einziges Foto jemals auf einen fremden Server hochgeladen wird. Die App ist mit klarem Fokus darauf ausgelegt, eine einzige Aufgabe richtig gut zu erledigen: Speicherplatz in einer Bibliothek zurückzugewinnen, die sich über Monate und Jahre still mit lästigen Duplikaten, nahezu identischen Serienbild-Sets, längst vergessenen Screenshots und Videos füllt, die einmal kurz aufgenommen und seither nie wieder angesehen wurden. Drei lokale Scans erledigen die schwere Arbeit im Hintergrund: Die exakte Duplikat-Erkennung gruppiert Fotos mit identischen Pixelmaßen, die in derselben Sekunde aufgenommen wurden und garantiert mehrfach vorhanden sind; die Serienbild-Erkennung verknüpft Fotos, die innerhalb von zehn Sekunden hintereinander entstanden sind und meist nur eine Variante lohnen; und die Screenshot-Erkennung greift direkt auf das dedizierte Screenshot-Album unter iOS zu oder durchsucht alternativ die Dateinamen. Jeder Scan liefert übersichtliche, prüfbare Gruppen, in denen jeweils die größte Datei als Favorit vorgeschlagen wird – die Entscheidung wird so zum ruhigen Blick statt zum mühsamen Vergleich. Neben der Bereinigung bietet die App eine monatsweise Wisch-Durchsicht für alles, was die automatischen Scans nicht erfassen, einen effizienten Bildkompressor, der die Dateigröße behaltenswerter Bilder ohne sichtbaren Qualitätsverlust deutlich reduziert, eine praktische Ansicht der größten Dateien, die die schwersten Inhalte zuerst auflistet, sowie einen integrierten Duplikat-Kontakte-Bereiniger, der neben der Fotobibliothek auch das Adressbuch im selben ruhigen Stil aufräumt. Jede einzelne Löschung läuft konsequent über die systemeigene Foto-Bibliothek und erfordert Ihre ausdrückliche Bestätigung, damit nichts versehentlich verschwindet. Pro entfernt Werbung dauerhaft; Nutzer der kostenlosen Version sehen pro Löschvorgang lediglich eine kurze, unaufdringliche Werbung.",
    es: "CleanPhoto es un limpiador de fotos para iOS que funciona por completo en tu teléfono, sin necesidad de cuenta y sin que ninguna foto se suba a ningún servidor. La app está diseñada para hacer bien una sola tarea: ayudarte a recuperar espacio en una biblioteca que se llena sin avisar de duplicados, ráfagas casi idénticas, capturas de pantalla antiguas y vídeos que grabaste una vez y nunca volviste a ver. Tres análisis locales hacen el trabajo pesado: la detección de duplicados exactos agrupa fotos con dimensiones idénticas capturadas en el mismo segundo, la detección de ráfagas encadena fotos tomadas en un intervalo de diez segundos, y la detección de capturas extrae las imágenes del álbum dedicado en iOS. Cada análisis produce grupos revisables donde el archivo más grande se presenta como el recomendado, para que la decisión sea un vistazo y no una comparación laboriosa. Además de la detección, la app incluye una revisión mensual por deslizamiento para todo lo que los análisis automáticos no detecten, un compresor de imágenes que reduce el tamaño de los archivos que quieres conservar sin pérdida visible de calidad, una vista de archivos grandes que muestra primero los elementos más pesados, y un limpiador de contacts duplicados que ordena la agenda junto con la biblioteca. Cada eliminación pasa por la fototeca del sistema con tu confirmación explícita, de modo que nada importante se borra por accidente. Pro elimina los anúncios y desbloquea lotes más grandes; los usuarios gratuitos ven un anuncio breve por cada lote de eliminación y conservan el acceso a todas las funciones de limpieza.",
    pt: "O CleanPhoto é um aplicativo grátis de limpeza de fotos para iOS que funciona inteiramente no seu celular, sem necessidade de conta e sem enviar nenhuma foto para servidor nenhum. Ele foi feito para fazer uma única tarefa bem: ajudar você a recuperar espaço em uma biblioteca que vai enchendo aos poucos com duplicatas, sequências quase iguais de fotos em rajada, capturas de tela antigas e vídeos gravados uma vez e nunca mais assistidos. Três verificações locais fazem o trabalho pesado: a detecção de duplicatas exatas agrupa fotos com as mesmas dimensões capturadas no mesmo segundo, a detecção de rajadas une fotos tiradas em um intervalo de até dez segundos uma da outra, e a detecção de capturas de tela separa os registros do álbum dedicado do iOS ou procura pelos nomes de arquivo no Android. Cada verificação gera grupos prontos para revisão, nos quais o maior arquivo aparece como o que vale a pena guardar, transformando a decisão em uma olhada rápida em vez de uma comparação trabalhosa. Além da limpeza principal, o app inclui uma revisão mês a mês com deslize para tudo o que as verificações automáticas não pegam, um compressor de imagens que reduz o tamanho dos arquivos que você quer manter sem perda visível de qualidade, uma visão dos arquivos maiores priorizando os itens mais pesados que estão ocupando mais espaço, e um removedor de contatos duplicados que organiza a agenda de endereços junto com a biblioteca de fotos. Cada exclusão passa pela biblioteca de fotos do sistema com sua confirmação explícita, garantindo que nada seja apagado sem a sua permissão. O Pro remove anúncios; usuários grátis assistem a um anúncio curto por lote de exclusão.",
    it: "CleanPhoto è un'app gratuita per iPhone che pulisce la libreria fotografica completamente in locale, senza account e senza che una sola foto venga caricata su un server. L'app è progettata per fare bene una cosa sola: aiutarti a recuperare spazio in una libreria che si riempie in silenzio di duplicati, scatti in sequenza quasi identici, vecchi screenshot e video che hai registrato una volta e non hai mai rivisto. Tre scansioni locali fanno il lavoro pesante: il rilevamento dei duplicati esatti raggruppa le foto con le stesse dimensioni scattate nello stesso secondo, il rilevamento delle sequenze collega le foto scattate entro dieci secondi l'una dall'altra, e il rilevamento degli screenshot pesca le catture dall'album apposito di iOS o analizza i nomi dei file su Android. Ogni scansione produce gruppi revisionabili in cui il file più grande viene proposto come quello da tenere, così la decisione diventa uno sguardo invece di un confronto. Oltre alla pulizia, l'app include una revisione mese per mese con scorrimento per tutto quello che le scansioni non colgono, un compressore di immagini che riduce i file da tenere senza perdita di qualità visibile, una vista dei file più grandi che mette in cima gli elementi più pesanti, e un pulitore di contatti duplicati che sistema la rubrica insieme alla libreria. Ogni eliminazione passa attraverso la libreria foto di sistema con la tua conferma esplicita. Pro rimuove la pubblicità; gli utenti gratuiti guardano un breve annuncio per ogni batch di eliminazione.",
    ru: "CleanPhoto — это бесплатный iOS-чистильщик фотографий, который работает целиком на вашем iPhone: не нужен ни аккаунт, ни загрузка снимков на какой-либо сервер. Приложение создано, чтобы выполнять одну задачу хорошо: возвращать вам место в библиотеке, которая незаметно наполняется дубликатами, почти одинаковыми сериями, старыми скриншотами и видео, которые вы однажды записали и больше не смотрели. Три локальных сканирования выполняют всю тяжёлую работу: поиск точных дубликатов группирует снимки с одинаковыми размерами, сделанные в одну и ту же секунду; обнаружение серий связывает фотографии, снятые в течение десяти секунд друг от друга; обнаружение скриншотов вытаскивает снимки из выделенного альбома в iOS или анализирует имена файлов на Android. Каждое сканирование выдаёт группы, которые удобно просматривать: самый большой файл предлагается оставить, так что выбор — это один взгляд, а не долгое сравнение. Помимо очистки, в приложении есть понедельный свайп-просмотр всего, что не поймали автоматические сканирования, компрессор изображений, который сжимает файлы, которые вы хотите сохранить, без видимой потери качества, вид больших файлов, сразу выводящий самые тяжёлые элементы первыми, и чистильщик дубликатов контактов, который наводит порядок в адресной книге параллельно с библиотекой. Каждое удаление проходит через системную фотобиблиотеку с вашего явного подтверждения, так что случайно потерять снимок невозможно. Pro убирает рекламу; пользователи бесплатной версии смотрят одно короткое рекламное объявление на каждую партию удалений.",
    th: "CleanPhoto คือแอปทำความสะอาดภาพฟรีบน iOS ที่ทำงานทั้งหมดบนโทรศัพท์ของคุณ โดยไม่ต้องสร้างบัญชีและไม่มีการอัปโหลดภาพไปยังเซิร์ฟเวอร์ใดๆ เลย แอปนี้ถูกออกแบบมาให้ทำงานหนึ่งอย่างได้ดี: ช่วยคุณเรียกคืนพื้นที่ในคลังภาพที่ค่อยๆ เต็มไปด้วยภาพซ้ำ ชุดภาพถ่ายต่อเนื่องที่คล้ายกัน ภาพหน้าจอเก่า และวิดีโอที่คุณบันทึกครั้งเดียวและไม่ได้ดูซ้ำ การสแกนในเครื่องสามแบบทำงานหนักให้คุณ: การตรวจจับภาพซ้ำแบบเหมือนกันทุกประการจะจัดกลุ่มภาพที่มีขนาดเท่ากันซึ่งถ่ายในวินาทีเดียวกัน การตรวจจับภาพต่อเนื่องจะเชื่อมโยงภาพที่ถ่ายภายในสิบวินาทีต่อกัน และการตรวจจับภาพหน้าจอจะดึงภาพจากอัลบั้มเฉพาะบน iOS หรือสแกนชื่อไฟล์บน Android การสแกนแต่ละครั้งจะสร้างกลุ่มที่ตรวจสอบได้ โดยนำเสนอไฟล์ที่ใหญ่ที่สุดเป็นภาพที่จะเก็บไว้ ดังนั้นการตัดสินใจจึงเป็นเพียงการมองเห็น ไม่ใช่การเปรียบเทียบ นอกเหนือจากการทำความสะอาด แอปยังมีการตรวจสอบแบบปัดทีละเดือนสำหรับทุกสิ่งที่การสแกนไม่จับได้ เครื่องมือบีบอัดภาพที่ลดขนาดไฟล์ที่คุณต้องการเก็บโดยไม่สูญเสียคุณภาพที่มองเห็น มุมมองไฟล์ขนาดใหญ่ที่แสดงรายการที่หนักที่สุดก่อน และเครื่องมือทำความสะอาดผู้ติดต่อที่ซ้ำกันซึ่งจัดระเบียบสมุดที่อยู่พร้อมกับคลังภาพ การลบทุกครั้งจะผ่านคลังภาพของระบบด้วยการยืนยันอย่างชัดเจนจากคุณ Pro จะลบโฆษณา ส่วนผู้ใช้ฟรีจะดูโฆษณาสั้นๆ หนึ่งโฆษณาต่อการลบแบบแบตช์ค่ะ"
  },
  "translate-offline-translator": {
    en: "Translate is a photo and voice translator built for travel, signage, and the moments when you do not have a working data connection. Snap a picture of a menu, a sign, a label, or a page in a foreign language, and the app extracts the text with on-device OCR, runs it through your downloaded language model, and overlays the translation on the original image. The same flow works on voice: hold the microphone, speak, and the translation arrives in your language; a playback button then reads the translated sentence aloud in the target language so you can hold the phone out to a taxi driver or shopkeeper and let them hear the question before you try to pronounce it yourself. The translation engine runs locally after a small per-language model is downloaded, so once the languages you need are installed the app works fully without internet — on the subway, on a plane, in a country where roaming is expensive. The library of supported languages covers most major markets, and a per-language indicator shows the model size on disk so you know exactly what each download costs before you tap it; models can be removed and re-downloaded at any time to free storage. The interface is available in fourteen languages, the core translator is free with a generous monthly quota, and a Pro subscription removes the quota and unlocks batch image translation. Translate does not upload your photos or your voice: OCR happens on the device, translation happens on the device, and only the model download itself touches the network.",
    zh: "Translate 是一款为旅行、看懂路牌，以及各种没网时刻打造的拍照与语音翻译 App。对着外文菜单、招牌、标签或书页拍一张照片，App 就会用设备端 OCR 提取文字，交给你已下载的语言模型翻译，再把译文叠加显示在原图上。语音翻译同样顺畅：按住麦克风说话，译文马上以你的语言呈现；再点播放键，App 会用目标语言把译句朗读出来，你可以直接把手机递给出租车司机或店员，先让对方听清楚问题，不必硬着头皮自己发音。翻译引擎在下载对应语言的小体积模型后完全在本地运行，所以只要装好你需要的语言，App 就能在完全没有网络的情况下正常使用——地铁里、飞机上，或是在漫游费贵得离谱的国家。支持的语种覆盖了大多数主流市场，每种语言都会标出模型占用的存储空间，让你在轻点下载前就心里有数；模型随时可以删除，也随时可以重新下载，方便释放空间。界面支持 14 种语言，核心翻译功能免费，且每月额度相当充裕；Pro 订阅可取消额度限制，并解锁批量图片翻译。Translate 不会上传你的照片和语音：OCR 在设备上完成，翻译也在设备上完成，只有下载模型这一步才会联网。",
    "zh-TW": "Translate 是一款專為旅行、告示牌辨識,以及沒有可用網路時所設計的拍照與語音翻譯 App。對著外文菜單、招牌、標籤或書頁拍照,App 便會透過裝置端 OCR 擷取文字,送進你下載好的語言模型,再把翻譯結果疊加回原始圖片上。語音翻譯流程同樣流暢:按住麥克風說話,翻譯結果便會以你的語言顯示;播放鍵還能用目標語言朗讀譯文,讓你把手機遞給計程車司機或店員,讓他們先聽到問題,你再試著發音。翻譯引擎在下載小型語言模型後於本機執行,所以一旦安裝好你所需的語言,App 就能在沒有網路的狀態下完整運作,無論是在地下鐵、飛機上,或在漫遊費昂貴的國家。支援的語言涵蓋大部分主要市場,每個語言都會顯示模型佔用空間,讓你在下載前就清楚知道容量成本;模型可隨時移除或重新下載,以釋放儲存空間。介面支援 14 種語言,核心翻譯功能免費,並提供充裕的每月額度;Pro 訂閱則能解除額度限制,並解鎖批次圖片翻譯。Translate 不會上傳你的照片或語音:OCR 在裝置端執行,翻譯在裝置端執行,只有模型下載本身會連線到網路。",
    ja: "Translateは、旅行や標識、通信環境が利用できない瞬間のために作られた、写真翻訳と音声翻訳に対応したアプリです。外国語のメニュー、看板、ラベル、ページの写真を撮ると、アプリが端末上のOCRで文字を抽出し、ダウンロード済みの言語モデルを通じて翻訳し、原文の画像上に翻訳結果を重ね合わせて表示します。同じ流れは音声でも機能します。マイクを長押しして話すと、あなたの言語に翻訳された結果が表示され、再生ボタンを押すと翻訳文が翻訳先の言語で読み上げられるため、タクシードライバーや店主の方にスマホを向けて、あなたが発音する前に質問内容を聞かせることができます。翻訳エンジンは、言語ごとの小さなモデルをダウンロードした後、ローカルで動作します。一度必要な言語をインストールすれば、インターネット接続のない地下鉄の中、機内、ローミング料金の高い国でも、アプリは完全に動作します。対応言語ライブラリは主要市場の大半をカバーし、言語ごとのモデルサイズをディスク容量で表示するため、ダウンロード前に必要な容量を正確に把握できます。モデルはいつでも削除して再ダウンロードでき、ストレージを節約できます。インターフェースは14言語に対応し、基本翻訳は無料かつ寛大な月間クォータ付きで利用可能で、Proのサブスクリプションではクォータ制限が解除され、画像の一括翻訳機能もご利用いただけます。Translateは写真や音声をアップロードしません。OCRは端末内で行われ、翻訳も端末内で行われ、ネットワークを使うのはモデルダウンロードのときだけです。",
    ko: "Translate는 여행, 표지판, 데이터 연결이 닿지 않는 순간을 위한 사진·음성 번역기입니다. 외국어 메뉴판, 간판, 라벨을 찍으면 기기 내 OCR로 텍스트를 추출하고 내려받은 모델로 번역해 원본 위에 자연스럽게 입혀 줍니다. 음성도 같은 흐름으로, 마이크를 눌러 말하면 내 언어로 번역이 도착하고 이어서 재생 버튼을 누르면 번역된 문장이 목표 언어로 읽혀 주어 택시 기사님께 먼저 들려드릴 수 있습니다. 언어 모델을 한 번 내려받으면 이후로는 기기 안에서 작동해 지하철, 비행기, 로밍비가 비싼 나라 어디서든 인터넷 없이 완전히 동작합니다. 지원 언어는 주요 시장을 망라하며 언어별 디스크 용량을 미리 표시해 탭 전에 비용을 확인할 수 있고, 필요할 때 언제든 삭제하고 다시 내려받을 수 있습니다. 인터페이스는 14개 언어로 제공되고 핵심 번역기는 넉넉한 월간 무료 제공량과 함께 무료이며, Pro 구독으로 제공량 제한을 없애고 이미지 일괄 번역을 열어 드립니다. 사진과 음성은 외부로 전송되지 않으며 OCR과 번역 모두 기기에서, 네트워크에 닿는 것은 모델 다운로드뿐입니다.",
    vi: "Translate là ứng dụng dịch qua ảnh và giọng nói được tạo ra cho du lịch, biển chỉ dẫn và những lúc bạn không có kết nối dữ liệu ổn định. Chụp một bức ảnh thực đơn, biển chỉ dẫn, nhãn mác hoặc một trang bằng ngôn ngữ nước ngoài, ứng dụng sẽ trích xuất văn bản bằng OCR trên thiết bị, chạy qua mô hình ngôn ngữ đã tải xuống của bạn, và phủ bản dịch lên chính ảnh gốc. Quy trình tương tự cũng hoạt động với giọng nói: nhấn giữ micro, nói, và bản dịch sẽ đến bằng ngôn ngữ của bạn; một nút phát sẽ đọc to câu đã dịch bằng ngôn ngữ đích để bạn có thể đưa điện thoại cho tài xế taxi hay người bán hàng nghe câu hỏi trước khi bạn cố phát âm. Bộ máy dịch chạy cục bộ sau khi một mô hình nhỏ theo từng ngôn ngữ được tải xuống, nên khi các ngôn ngữ bạn cần đã được cài đặt, ứng dụng hoạt động hoàn toàn không cần internet — trong tàu điện ngầm, trên máy bay, ở một quốc gia mà cước chuyển vùng đắt đỏ. Thư viện ngôn ngữ hỗ trợ bao phủ hầu hết các thị trường lớn, và một chỉ báo theo ngôn ngữ hiển thị kích thước mô hình trên ổ đĩa để bạn biết chính xác mỗi lượt tải xuống tốn bao nhiêu trước khi chạm; các mô hình có thể xóa và tải lại bất kỳ lúc nào để giải phóng dung lượng. Giao diện có sẵn bằng 14 ngôn ngữ, trình dịch cốt lõi miễn phí với hạn mức hằng tháng hào phóng, và gói đăng ký Pro sẽ bỏ hạn mức cùng mở khóa dịch ảnh hàng loạt. Translate không tải lên ảnh hay giọng nói của bạn: OCR diễn ra trên thiết bị, bản dịch diễn ra trên thiết bị, và chỉ bản thân lượt tải mô hình chạm vào mạng.",
    id: "Translate adalah penerjemah foto dan suara yang dirancang khusus untuk kebutuhan bepergian ke luar negeri, membaca rambu jalan asing, dan momen-momen ketika kamu sedang tidak punya koneksi data yang bisa diandalkan. Cukup jepret foto sebuah menu restoran, rambu jalan, label produk, atau halaman buku dalam bahasa asing, dan aplikasinya akan secara otomatis mengekstrak teksnya lewat fitur OCR yang berjalan langsung di perangkat, lalu menjalankannya melalui model bahasa yang sudah kamu unduh sebelumnya, dan terakhir menampilkan terjemahan yang ditumpangkan rapi di atas gambar aslinya. Alur kerja yang sama persis juga berlaku untuk input suara: tahan tombol mikrofon, ucapkan kalimatmu dengan jelas, dan hasil terjemahan akan tiba dalam bahasa yang kamu pahami; tombol playback kemudian membacakan kalimat terjemahan tersebut dengan suara keras dalam bahasa target, sehingga kamu bisa mengarahkan HP ke sopir taksi atau penjaga toko lokal dan membiarkan mereka mendengar pertanyaannya terlebih dahulu sebelum kamu mencoba mengucapkannya sendiri. Mesin penerjemahan di dalam aplikasi ini berjalan secara lokal setelah model per-bahasa yang berukuran kecil diunduh satu kali di awal, jadi begitu bahasa-bahasa yang kamu butuhkan sudah terpasang di perangkat, aplikasinya bisa bekerja sepenuhnya tanpa koneksi internet — di dalam kereta bawah tanah, di dalam pesawat, atau di sebuah negara dengan tarif roaming yang sangat mahal. Perpustakaan bahasa yang didukung mencakup sebagian besar pasar utama di seluruh dunia, dan indikator per-bahasa menunjukkan ukuran model di penyimpanan lokal supaya kamu tahu persis berapa ruang penyimpanan yang akan terpakai oleh tiap unduhan sebelum benar-benar mengetuk tombol unduh; semua model bahasa ini juga bisa dihapus dan diunduh ulang kapan saja kalau kamu butuh menghemat ruang penyimpanan di kemudian hari. Antarmukanya tersedia dalam 14 bahasa, fitur penerjemah intinya gratis dengan kuota bulanan yang generous, dan langganan Pro menghilangkan kuota tersebut serta membuka kemampuan terjemahan gambar secara batch sekaligus. Translate tidak pernah mengunggah fotomu dan tidak pernah mengunggah rekaman suaramu ke server mana pun: seluruh proses OCR terjadi di perangkat, seluruh proses penerjemahan terjadi di perangkat, dan satu-satunya hal yang menyentuh jaringan adalah saat pertama kali kamu mengunduh model bahasa itu sendiri.",
    ar: "تطبيق Translate هو مترجم صوتي ومبني على الصور، صُمم للسفر واللافتات واللحظات التي لا يتوفر فيها اتصال بيانات. التقط صورة لقائمة طعام أو لافتة أو ملصق أو صفحة بلغة أجنبية، ويستخرج التطبيق النص باستخدام OCR على الجهاز، ويمرّره عبر نموذج اللغة المحمّل، ويعرض الترجمة متراكبة على الصورة الأصلية في موضع النص نفسه. يعمل التدفق نفسه بالصوت: اضغط مع الاستمرار على الميكروفون وتحدّث، فتصل الترجمة إلى لغتك خلال ثوانٍ؛ ثم يقرأ زر تشغيل الترجمة الجملة المترجمة بصوت عالٍ باللغة المستهدفة، لتُخرج الهاتف لسائق تاكسي أو صاحب متجر ويسمع السؤال قبل أن تحاول نطقه بنفسك. يعمل محرك الترجمة محليًا بعد تنزيل نموذج صغير لكل لغة، فبمجرد تثبيت اللغات التي تحتاجها يعمل التطبيق بالكامل دون اتصال — في المترو، أو على الطائرة، أو في دولة يكون فيها التجوال مكلفًا. تغطي مكتبة اللغات المدعومة أغلب الأسواق الرئيسية حول العالم، ويشير مؤشر خاص لكل لغة إلى حجم النموذج على القرص لتعرف بالضبط تكلفة كل تنزيل قبل النقر عليه؛ ويمكن إزالة النماذج وإعادة تنزيلها في أي وقت لتحرير مساحة التخزين. الواجهة متاحة بـ ١٤ لغة، والمترجم الأساسي مجاني مع حصة شهرية سخية، واشتراك Pro يزيل الحصة ويفتح ترجمة الصور بالدفعات. لا يرفع Translate صورك أو صوتك: تحدث OCR على الجهاز، وتحدث الترجمة على الجهاز، ولا يلامس الشبكة سوى تنزيل النموذج نفسه.",
    fr: "Translate est un traducteur photo et voix conçu pour le voyage, la signalétique et les moments où vous ne disposez pas d'une connexion de données fonctionnelle. Prenez en photo un menu, un panneau, une étiquette ou une page en langue étrangère, et l'application extrait le texte par OCR sur l'appareil, le passe à travers le modèle linguistique téléchargé, puis superpose la traduction sur l'image d'origine. Le même flux fonctionne pour la voix : maintenez le micro, parlez, et la traduction arrive dans votre langue ; un bouton de lecture lit ensuite la phrase traduite à voix haute dans la langue cible, pour que vous puissiez tendre le téléphone à un chauffeur de taxi ou à un commerçant et lui faire entendre la question avant d'essayer vous-même de la prononcer. Le moteur de traduction fonctionne localement après le téléchargement d'un petit modèle par langue : une fois les langues dont vous avez besoin installées, l'application est pleinement opérationnelle sans internet — dans le métro, dans un avion, dans un pays où l'itinérance coûte cher. La bibliothèque de langues prises en charge couvre les principaux marchés, et un indicateur par langue affiche la taille du modèle sur le disque pour que vous sachiez exactement ce que chaque téléchargement vous coûte avant d'appuyer dessus ; les modèles peuvent être supprimés et retéléchargés à tout moment afin de récupérer de l'espace de stockage. L'interface est disponible en 14 langues, le traducteur principal est gratuit avec un quota mensuel généreux, et un abonnement Pro supprime le quota et débloque la traduction d'images par lots. Translate ne téléverse ni vos photos ni votre voix : l'OCR s'effectue sur l'appareil, la traduction s'effectue sur l'appareil, et seul le téléchargement du modèle touche au réseau.",
    de: "Translate ist ein Foto- und Sprachübersetzer, der gezielt für Reisen, Beschilderung im Alltag und all die Momente entwickelt wurde, in denen keine funktionierende Datenverbindung zur Verfügung steht. Fotografieren Sie einfach eine Speisekarte, ein Straßenschild, ein Etikett oder eine Seite in einer fremden Sprache, und die App extrahiert den Text mit schneller On-Device-OCR, leitet ihn durch Ihr lokal gespeichertes Sprachmodell und legt die Übersetzung als gut lesbare Überlagerung über das Originalbild. Derselbe komfortable Ablauf funktioniert genauso mit gesprochener Sprache: Halten Sie das Mikrofon gedrückt, sprechen Sie Ihren Satz, und die Übersetzung erscheint in Ihrer Wunschsprache; ein integrierter Wiedergabe-Button liest den übersetzten Satz anschließend in der Zielsprache vor, sodass Sie dem Taxifahrer oder dem Ladenbesitzer das iPhone einfach hinhalten und die Frage direkt hören lassen können, bevor Sie sie selbst aussprechen müssen. Die leistungsfähige Übersetzungs-Engine läuft komplett lokal, sobald ein kleines, pro Sprache einzeln heruntergeladenes Modell auf dem Gerät liegt – sind die benötigten Sprachen installiert, arbeitet die App vollständig ohne Internet, sei es in der U-Bahn, im Flugzeug oder in einem Land mit besonders teurem Roaming. Die Bibliothek unterstützter Sprachen deckt die meisten wichtigen Märkte weltweit ab, und eine ehrliche Anzeige pro Sprache zeigt die jeweilige Modellgröße auf dem Gerät an, damit Sie bereits vor dem Antippen genau wissen, wie viel Speicher der Download kostet; Modelle lassen sich jederzeit rückstandsfrei entfernen und bei Bedarf erneut herunterladen, um Speicherplatz wieder freizugeben. Die Benutzeroberfläche ist in 14 Sprachen verfügbar, der Kernübersetzer ist mit einem großzügigen monatlichen Kontingent kostenlos, und ein Pro-Abonnement entfernt dieses Kontingent vollständig und schaltet zusätzlich die komfortable Bild-Stapelübersetzung für mehrere Fotos auf einmal frei. Translate lädt weder Ihre Fotos noch Ihre Sprachaufnahmen irgendwo hoch: OCR geschieht ausschließlich auf dem Gerät, die Übersetzung geschieht ausschließlich auf dem Gerät, und einzig der ursprüngliche Modell-Download selbst berührt überhaupt das Netzwerk.",
    es: "Translate es un traductor por foto y voz pensado para viajes, señalización y esos momentos en los que no dispones de una conexión de datos estable. Captura una imagen de un menú, una señal, una etiqueta o una página en otro idioma, y la app extrae el texto con OCR en el dispositivo, lo pasa por tu modelo de idioma descargado y superpone la traducción sobre la imagen original para que compares ambos al instante. El mismo flujo funciona con voz: mantén pulsado el micrófono, habla y la traducción llega a tu idioma; un botón de reproducción lee después la frase traducida en voz alta en el idioma de destino, para que puedas acercar el teléfono a un taxista o a un comerciante y dejar que escuchen la pregunta antes de que intentes pronunciarla tú. El motor de traducción funciona en local después de descargar un pequeño modelo por idioma, así que una vez instalados los idiomas que necesitas, la app opera completamente sin conexión: en el metro, en un avión, en un país donde el roaming es caro o en una zona rural sin cobertura. La biblioteca de idiomas compatibles cubre la mayoría de los mercados principales, y un indicador por idioma muestra el tamaño del modelo en disco para que sepas exactamente qué ocupa cada descarga antes de tocar; los modelos pueden eliminarse y volver a descargarse en cualquier momento para liberar almacenamiento. La interfaz está disponible en 14 idiomas, el traductor básico es gratis con una cuota mensual generosa, y una suscripción Pro elimina la cuota y desbloquea la traducción por lotes de imágenes y los modelos de voz más avanzados. Translate no sube tus fotos ni tu voz: el OCR ocurre en el dispositivo, la traducción ocurre en el dispositivo, y solo la descarga del modelo toca la red.",
    pt: "O Translate é um tradutor por foto e voz feito para viagens, placas e os momentos em que você não tem uma conexão de dados funcionando. Tire uma foto de um cardápio, uma placa, um rótulo ou uma página inteira em idioma estrangeiro, e o app extrai o texto com OCR no próprio aparelho, passa pelo modelo de idioma baixado e sobrepõe a tradução na imagem original. O mesmo fluxo funciona com voz: segure o microfone, fale, e a tradução chega no seu idioma em tempo real; um botão de reprodução lê em voz alta a frase traduzida no idioma de destino, para você estender o celular para um taxista ou um balconista e deixar a pergunta ser ouvida antes de você tentar pronunciar. O motor de tradução roda localmente depois que um pequeno modelo por idioma é baixado, então, uma vez instalados os idiomas que você precisa, o app funciona totalmente sem internet — no metrô, no avião, em um país onde o roaming é caro ou simplesmente indisponível. A biblioteca de idiomas compatíveis cobre a maior parte dos principais mercados do mundo, e um indicador por idioma mostra o tamanho do modelo no armazenamento, para você saber exatamente o que cada download custa antes de tocar; os modelos podem ser removidos e baixados de novo a qualquer momento para liberar espaço no aparelho. A interface está disponível em 14 idiomas, o tradutor principal é gratuito com uma cota mensal generosa, e uma assinatura Pro remove a cota e libera a tradução de imagens em lote para quem precisa processar várias fotos rapidamente. O Translate não envia suas fotos nem sua voz: o OCR acontece no aparelho, a tradução acontece no aparelho, e apenas o download inicial do modelo em si acessa a rede.",
    it: "Translate è un traduttore di foto e voce pensato per i viaggi, la segnaletica e i momenti in cui non hai una connessione dati che funzioni. Scatta una foto a un menu, un cartello, un'etichetta o una pagina in una lingua straniera, e l'app estrae il testo con un OCR in locale, lo passa attraverso il modello linguistico che hai scaricato e sovrappone la traduzione all'immagine originale. Lo stesso flusso funziona con la voce: tieni premuto il microfono, parla, e la traduzione arriva nella tua lingua; un pulsante di riproduzione legge poi la frase tradotta ad alta voce nella lingua di destinazione, così puoi porgere il telefono a un tassista o a un commesso e fargli sentire la domanda prima di provare a pronunciarla tu. Il motore di traduzione gira in locale dopo aver scaricato un piccolo modello per ciascuna lingua, quindi una volta installate le lingue che ti servono l'app funziona completamente senza internet — in metropolitana, in aereo, in un paese dove il roaming è caro. La libreria delle lingue supportate copre i principali mercati, e un indicatore per lingua mostra la dimensione del modello su disco così sai esattamente quanto ti costa ogni download prima di toccare; i modelli si possono rimuovere e riscaricare in qualsiasi momento per liberare spazio. L'interfaccia è disponibile in quattordici lingue, il traduttore base è gratuito con una quota mensile generosa, e un abbonamento Pro rimuove la quota e sblocca la traduzione di immagini in batch. Translate non carica le tue foto né la tua voce: l'OCR succede sul dispositivo, la traduzione succede sul dispositivo, e solo il download del modello tocca la rete.",
    ru: "Translate — это переводчик по фото и голосовому вводу, созданный для путешествий, вывесок и тех моментов, когда под рукой нет рабочего интернета. Сфотографируйте меню, вывеску, этикетку или страницу на иностранном языке — приложение распознает текст с помощью OCR на устройстве, пропустит его через загруженную языковую модель и наложит перевод поверх исходного изображения. Тот же сценарий работает для голоса: зажмите микрофон, говорите — перевод появится на вашем языке; кнопка воспроизведения затем озвучивает переведённую фразу на языке перевода, чтобы вы могли показать iPhone таксисту или продавцу и дать им услышать вопрос раньше, чем вы сами попытаетесь его произнести. Движок перевода работает локально после того, как загружена небольшая языковая модель, поэтому, как только нужные вам языки установлены, приложение полностью работает без интернета — в метро, в самолёте, в стране, где роуминг стоит дорого. Библиотека поддерживаемых языков охватывает большинство крупных рынков, а индикатор для каждого языка показывает размер модели на диске — вы заранее знаете, сколько стоит каждая загрузка, прежде чем нажать; модели можно удалить и снова загрузить в любой момент, чтобы освободить место. Интерфейс доступен на 14 языках, основной переводчик бесплатен с щедрым месячным лимитом, а подписка Pro снимает лимит и открывает пакетный перевод изображений. Translate не выгружает ваши фото и голос: OCR происходит на устройстве, перевод происходит на устройстве, и только сама загрузка модели касается сети.",
    th: "Translate คือแอปแปลภาพและเสียงที่สร้างมาสำหรับการเดินทาง ป้ายสัญญาณ และช่วงเวลาที่คุณไม่มีการเชื่อมต่อข้อมูลที่ใช้งานได้ ถ่ายภาพเมนู ป้าย ฉลาก หรือหน้าหนังสือในภาษาต่างประเทศ แล้วแอปจะดึงข้อความด้วย OCR บนอุปกรณ์ รันผ่านโมเดลภาษาที่ดาวน์โหลดไว้ และซ้อนการแปลบนภาพต้นฉบับ กระบวนการเดียวกันนี้ใช้ได้กับเสียง: กดไมโครโฟนค้างไว้ พูด แล้วการแปลจะมาถึงในภาษาของคุณ จากนั้นปุ่มเล่นจะอ่านประโยคที่แปลแล้วออกเสียงในภาษาเป้าหมาย เพื่อให้คุณยื่นโทรศัพท์ให้คนขับแท็กซี่หรือคนขายของได้ยินคำถามก่อนที่คุณจะพยายามออกเสียงเอง เอนจินการแปลทำงานในเครื่องหลังจากดาวน์โหลดโมเดลภาษาขนาดเล็กแต่ละภาษา ดังนั้นเมื่อติดตั้งภาษาที่คุณต้องการแล้ว แอปจะทำงานได้อย่างเต็มที่โดยไม่ต้องใช้อินเทอร์เน็ต บนรถไฟใต้ดิน บนเครื่องบิน ในประเทศที่โรมมิ่งมีราคาแพง คลังภาษาที่รองรับครอบคลุมตลาดหลักส่วนใหญ่ และตัวบ่งชี้แต่ละภาษาแสดงขนาดโมเดลบนดิสก์ เพื่อให้คุณรู้ว่าแต่ละการดาวน์โหลดมีค่าใช้จ่ายเท่าใดก่อนแตะ สามารถลบและดาวน์โหลดโมเดลใหม่ได้ทุกเมื่อเพื่อเพิ่มพื้นที่จัดเก็บ อินเทอร์เฟซรองรับ 14 ภาษา ตัวแปลหลักใช้งานได้ฟรีพร้อมโควตารายเดือนที่ให้ generous และการสมัครสมาชิก Pro จะลบโควตาและปลดล็อกการแปลภาพแบบแบตช์ Translate ไม่อัปโหลดภาพหรือเสียงของคุณ: OCR เกิดขึ้นบนอุปกรณ์ การแปลเกิดขึ้นบนอุปกรณ์ และมีเพียงการดาวน์โหลดโมเดลเท่านั้นที่ใช้เครือข่ายค่ะ"
  },
  "paperscan": {
    en: "Paper Scan is a professional document scanner for iPhone that turns stacks of paper into clean, searchable PDFs without sending a single page to the cloud. The capture window uses the ultra-wide lens so a full A4 page fits edge to edge without distortion; six GPU-accelerated filters — Magic, Enhanced, Grayscale, B&W, Original, and Photo — handle everything from a faded receipt to a colour magazine page; on-device OCR detects the source language automatically and extracts the text from every page, then indexes it inside the PDF so any word is searchable later in the language it was written in. Multi-page documents are assembled automatically, named and dated, saved into organised folders, and can be reordered or have pages removed before export if a stray cover sheet slipped into the batch. The export step writes a PDF or a per-page image bundle to the Files app, iCloud Drive, Google Drive, Dropbox, or any other cloud target your device supports, and the export flow includes a conflict resolver so two scans of the same document never overwrite each other. Every operation — capture, filter, OCR, assembly, export — runs locally, with no account and no upload. The interface is available in fourteen languages, the scanner and PDF export are free, and Pro adds cloud sync, batch OCR, and removes ads. Paper Scan is built for the moments when you need the paper gone but the record kept.",
    zh: "Paper Scan 是一款专业的 iPhone 文档扫描 App，能把一摞摞纸质文件变成清晰、可搜索的 PDF，而且一页都不会传上云端。取景界面采用超广角镜头，整张 A4 纸能完整入画且不变形；六种 GPU 加速滤镜——Magic、Enhanced、Grayscale、B&W、Original 和 Photo——从褪色的小票到彩色杂志内页都能轻松应对；设备端 OCR 会自动识别原文语种，提取每一页的文字并索引进 PDF，日后你可以直接用原文语言搜索任何一个词。多页文档会自动拼装、命名并标注日期，归入井井有条的文件夹，导出前还能重新排序或删掉某几页，万一有张封面页混进了批次也不怕。导出时可以把 PDF 或逐页图片包写入“文件”App、iCloud Drive、Google Drive、Dropbox，或你设备支持的任意云端位置，导出流程还内置了冲突处理机制，同一份文档扫描两次也不会互相覆盖。拍摄、滤镜、OCR、拼装、导出，每一步都在本地运行，无需账号，绝不上传。界面支持 14 种语言，扫描和 PDF 导出功能免费，Pro 则增加云同步、批量 OCR 并去除广告。Paper Scan 就是为那些“纸可以扔，记录必须留”的时刻而生。",
    "zh-TW": "Paper Scan 是一款專業的 iPhone 文件掃描器,能把一疊疊紙本轉成乾淨、可搜尋的 PDF,完全不必把任何一頁送上雲端。取景畫面採用超廣角鏡頭,讓整張 A4 頁面能邊對邊完整入鏡而不失真;六種 GPU 加速濾鏡包含 Magic、Enhanced、Grayscale、B&W、Original 與 Photo,從褪色收據到彩色雜誌頁都能完美處理;裝置端 OCR 會自動偵測來源語言,擷取每頁文字後直接索引進 PDF,讓你日後能以原文語言搜尋任何字詞。多頁文件會自動組裝、命名並標註日期,儲存至井然有序的資料夾中;若有封面頁混入批次,還能在匯出前重新排序或刪除頁面。匯出步驟可將 PDF 或逐頁圖片包寫入檔案 App、iCloud Drive、Google Drive、Dropbox,或裝置支援的任何雲端目的地,匯出流程還內建衝突解決機制,避免同一份文件的兩次掃描互相覆蓋。每一道操作,從拍攝、濾鏡、OCR、組裝到匯出,都在本機執行,無需帳號也沒有上傳。介面支援 14 種語言,掃描與 PDF 匯出功能免費,Pro 版則加入雲端同步、批次 OCR 與去除廣告功能。Paper Scan 專為那些需要讓紙本消失、卻又想留存紀錄的時刻而生。",
    ja: "Paper Scanは、紙の束をクラウドに送信することなく、クリーンでテキスト検索可能なPDFに変換するiPhone向けプロフェッショナル文書スキャナーです。キャプチャ画面では超広角レンズを使用するため、A4用紙の全体が歪まずに端から端まで収まります。Magic、Enhanced、Grayscale、B&W、Original、Photoの6つのGPUアクセラレーションフィルターが、色あせたレシートからカラフルな雑誌のページまで、あらゆる文書に対応します。端末上のOCRが元の言語を自動で検出し、すべてのページからテキストを抽出してPDF内にインデックス化するため、あとからその言語で検索が可能です。複数ページの文書は自動でまとめられ、命名されて日付が入り、整理されたフォルダーに保存されます。不要な表紙が紛れ込んだ場合など、書き出し前にページの並べ替えや削除もできます。書き出しステップでは、PDF形式またはページ単位の画像束を、Filesアプリ、iCloud Drive、Google Drive、Dropbox、お使いのデバイスが対応するその他のクラウド保存先に書き出せます。書き出しフローには競合解決機能が含まれているため、同じ文書を2回スキャンしても上書きされることはありません。キャプチャ、フィルター、OCR、組み立て、書き出しまで、すべての操作がローカルで実行され、アカウントもアップロードも不要です。インターフェースは14言語に対応し、スキャナーとPDF書き出しは無料でご利用いただけます。Proではクラウド同期、バッチOCR、広告削除が追加されます。Paper Scanは、紙は処分したい、でも記録は残しておきたいという瞬間のために作られました。",
    ko: "Paper Scan은 종이 한 장도 구름에 보내지 않고 깔끔하고 검색 가능한 PDF로 바꿔 주는 iPhone용 문서 스캐너입니다. 초광각 렌즈로 A4 페이지를 왜곡 없이 담고, 6가지 GPU 가속 필터(Magic, Enhanced, Grayscale, B&W, Original, Photo)가 바랜 영수증부터 컬러 잡지까지 처리합니다. 기기 내 OCR이 원문 언어를 자동 감지해 텍스트를 추출하고 PDF 안에 색인을 구축해 원래 언어로 어떤 단어든 검색할 수 있게 합니다. 여러 장 문서는 자동으로 묶이고 이름, 날짜, 폴더로 정리되며 내보내기 전 순서 변경이나 페이지 제거도 가능합니다. PDF 또는 이미지 묶음을 파일 앱, iCloud Drive, Google Drive, Dropbox 등 모든 클라우드 대상으로 저장할 수 있고 같은 문서 두 번 스캔 시 충돌 해결 기능이 함께 제공됩니다. 캡처, 필터, OCR, 조립, 내보내기까지 모두 로컬에서 실행되며 계정과 업로드는 없습니다. 인터페이스는 14개 언어로 제공되고 스캐너와 PDF 내보내기는 무료이며, Pro 구독으로 클라우드 동기화, 대량 OCR, 광고 제거가 추가됩니다.",
    vi: "Paper Scan là máy quét tài liệu chuyên nghiệp trên iPhone biến chồng giấy thành các tệp PDF sạch sẽ và có thể tìm kiếm mà không gửi đi một trang nào lên đám mây. Cửa sổ chụp sử dụng ống kính góc siêu rộng để cả trang A4 vừa khít từ mép này sang mép kia mà không méo; sáu bộ lọc tăng tốc bằng GPU — Magic, Enhanced, Grayscale, B&W, Original và Photo — xử lý mọi thứ từ hóa đơn đã phai màu đến một trang tạp chí đầy màu sắc; OCR trên thiết bị tự động phát hiện ngôn ngữ gốc và trích xuất văn bản từ mỗi trang, sau đó lập chỉ mục ngay bên trong tệp PDF để bất kỳ từ nào cũng có thể tìm được sau này bằng đúng ngôn ngữ đã viết. Tài liệu nhiều trang được ghép tự động, đặt tên và ghi ngày, lưu vào các thư mục có tổ chức, đồng thời có thể sắp xếp lại hoặc xóa bớt trang trước khi xuất nếu lỡ một bìa trang lẫn vào lô. Bước xuất ghi một tệp PDF hoặc bộ ảnh theo từng trang vào ứng dụng Tệp, iCloud Drive, Google Drive, Dropbox hoặc bất kỳ đích đám mây nào mà thiết bị của bạn hỗ trợ, và luồng xuất kèm theo trình giải quyết xung đột để hai lần quét cùng một tài liệu không bao giờ ghi đè lên nhau. Mọi thao tác — chụp, lọc, OCR, ghép, xuất — đều chạy cục bộ, không cần tài khoản và không tải lên. Giao diện có sẵn bằng 14 ngôn ngữ, máy quét và xuất PDF miễn phí, và Pro bổ sung đồng bộ đám mây, OCR hàng loạt cùng xóa quảng cáo. Paper Scan được tạo ra cho những lúc bạn cần giấy tờ biến mất nhưng hồ sơ phải được giữ lại.",
    id: "Paper Scan adalah pemindai dokumen profesional untuk iPhone yang mampu mengubah tumpukan kertas fisik di meja kerjamu menjadi file PDF yang bersih, rapi, terorganisir, dan sepenuhnya bisa dicari kata-katanya, tanpa mengirim satu halaman pun ke layanan cloud pihak ketiga. Jendela tangkap kamera di dalam aplikasi memakai lensa ultra-wide secara bawaan, sehingga satu halaman A4 penuh bisa muat dari ujung ke ujung tanpa distorsi tepi yang mengganggu; enam filter dengan akselerasi GPU — Magic, Enhanced, Grayscale, B&W, Original, dan Photo — menangani semua jenis dokumen, mulai dari struk belanja yang sudah mulai memudar warnanya hingga halaman majalah berwarna penuh yang penuh detail. Fitur OCR yang berjalan di perangkat akan mendeteksi bahasa sumber secara otomatis dan mengekstrak teks dari setiap halaman yang dipindai, lalu mengindeks teks tersebut langsung di dalam file PDF sehingga kata apa pun bisa dicari kemudian dalam bahasa aslinya sendiri ketika kamu butuh menemukan sesuatu dengan cepat. Dokumen multi-halaman akan dirakit secara otomatis oleh aplikasi, diberi nama dan tanggal secara otomatis, disimpan ke dalam folder-folder yang terorganisir rapi, dan bisa diurutkan ulang atau dihapus halamannya sebelum proses ekspor kalau ternyata ada halaman sampul atau halaman kosong yang keliru masuk ke dalam satu batch pemindaian. Langkah ekspor akhir akan menulis file PDF atau bundel gambar per-halaman langsung ke app Files di iPhone, iCloud Drive, Google Drive, Dropbox, atau target cloud lain apa pun yang didukung oleh perangkatmu, dan alur ekspor sudah mencakup pemecah konflik bawaan supaya dua hasil pemindaian dari dokumen fisik yang sama tidak akan pernah saling menimpa file satu sama lain. Setiap operasi di dalam aplikasi — mulai dari penangkapan kamera, penerapan filter visual, OCR, perakitan dokumen, hingga proses ekspor — semuanya berjalan secara lokal di perangkat, tanpa butuh akun dan tanpa ada satu pun data yang diunggah ke server eksternal. Antarmukanya tersedia dalam 14 bahasa, fitur pemindai dan ekspor PDF intinya gratis untuk dipakai, dan versi Pro menambahkan kemampuan sinkronisasi cloud, OCR batch untuk banyak dokumen sekaligus, serta menghilangkan iklan dari tampilan aplikasi. Paper Scan pada dasarnya dibuat khusus untuk momen-momen ketika kamu butuh kertas fisiknya hilang dari meja kerjamu, tetapi catatan dan informasi penting di dalamnya tetap harus tersimpan rapi dan bisa ditemukan kembali kapan saja dibutuhkan.",
    ar: "تطبيق Paper Scan هو ماسح ضوئي احترافي للمستندات على iPhone، يحوّل أكوام الورق إلى ملفات PDF نظيفة وقابلة للبحث دون إرسال صفحة واحدة إلى السحابة. تستخدم نافذة الالتقاط العدسة فائقة الاتساع ليتسع حجم صفحة A4 كاملة من الحافة إلى الحافة دون تشويه؛ وتعالج ست مرشّحات مدعومة بوحدة GPU — Magic وEnhanced وGrayscale وB&W وOriginal وPhoto — كل شيء من إيصال باهت إلى صفحة مجلة ملوّنة بنقرة واحدة؛ ويكتشف OCR على الجهاز لغة المصدر تلقائيًا ويستخرج النص من كل صفحة بدقة، ثم يفهرسه داخل ملف PDF ليصبح أي كلمة قابلة للبحث لاحقًا باللغة التي كُتبت بها. تُجمَّع المستندات متعددة الصفحات تلقائيًا، وتُسمّى وتُؤرَّخ، وتُحفظ في مجلدات منظّمة يسهل الوصول إليها، ويمكن إعادة ترتيبها أو إزالة صفحات منها قبل التصدير إن زلّت ورقة غلاف داخل الدفعة. تكتب خطوة التصدير ملف PDF أو حزمة صور صفحة بصفحة إلى تطبيق الملفات، أو iCloud Drive، أو Google Drive، أو Dropbox، أو أي هدف سحابي آخر يدعمه جهازك، ويتضمّن تدفق التصدير حلّ تعارضات حتى لا تطمس نسختان لنفس المستند إحداهما الأخرى عند الحفظ. كل عملية — الالتقاط، والترشيح، وOCR، والتجميع، والتصدير — تعمل محليًا، دون حساب ودون رفع إلى أي خادم خارجي. الواجهة متاحة بـ ١٤ لغة، والماسح وتصدير PDF مجانيان للجميع، وتضيف Pro مزامنة سحابية وOCR دفعيًا وإزالة الإعلانات. صُمم Paper Scan للحظات التي تحتاج فيها إلى اختفاء الورق مع الاحتفاظ بالسجل بشكل دائم.",
    fr: "Paper Scan est un scanner de documents professionnel pour iPhone qui transforme des piles de papier en PDF propres et interrogeables, sans envoyer la moindre page dans le cloud. La fenêtre de capture utilise l'objectif ultra grand-angle pour qu'une page A4 complète tienne bord à bord sans distorsion ; six filtres accélérés par GPU — Magic, Enhanced, Grayscale, B&W, Original et Photo — traitent aussi bien un ticket de caisse passé qu'une page de magazine en couleurs ; l'OCR embarqué détecte automatiquement la langue source et extrait le texte de chaque page, puis l'indexe à l'intérieur du PDF pour que n'importe quel mot soit recherchable ultérieurement, dans la langue dans laquelle il a été écrit. Les documents multipages sont assemblés automatiquement, nommés et datés, sauvegardés dans des dossiers organisés, et peuvent être réordonnés ou voir certaines pages supprimées avant l'export si une feuille de couverture s'est glissée dans le lot. L'étape d'export écrit un PDF ou un lot d'images par page dans l'app Fichiers, iCloud Drive, Google Drive, Dropbox, ou toute autre cible cloud prise en charge par votre appareil, et le flux d'export inclut un résolveur de conflits pour que deux scans du même document ne s'écrasent jamais mutuellement. Chaque opération — capture, filtre, OCR, assemblage, export — s'exécute localement, sans compte et sans téléversement. L'interface est disponible en 14 langues, le scanner et l'export PDF sont gratuits, et Pro ajoute la synchronisation cloud, l'OCR par lots, et supprime les publicités. Paper Scan est conçu pour ces moments où il vous faut faire disparaître le papier tout en conservant la trace.",
    de: "Paper Scan ist ein professioneller Dokumenten-Scanner für das iPhone, der selbst dicke Papierstapel in saubere, durchsuchbare PDFs verwandelt – ohne eine einzige Seite in die Cloud zu senden oder ein Konto zu verlangen. Das großzügige Aufnahmefenster nutzt die Ultraweitwinkel-Kamera, sodass eine vollständige A4-Seite randlos und ohne lästige Verzerrung in einem einzigen Foto erfasst wird; sechs GPU-beschleunigte Filter – Magic, Enhanced, Grayscale, B&W, Original und Photo – bewältigen zuverlässig alles vom verblassten Kassenbeleg über das handschriftliche Protokoll bis zur bunten Magazinseite. Eine schnelle On-Device-OCR erkennt die Ausgangssprache automatisch und extrahiert den Text jeder Seite, indexiert ihn anschließend direkt im PDF, sodass jedes einzelne Wort später in genau der Sprache durchsuchbar ist, in der es ursprünglich geschrieben wurde. Mehrseitige Dokumente werden automatisch zu einem sauberen Dokument zusammengestellt, mit aussagekräftigem Namen und Datum versehen, in übersichtlichen Ordnern abgelegt und können vor dem Export bequem umsortiert oder um einzelne Seiten gekürzt werden, falls sich versehentlich ein leeres Deckblatt eingeschlichen hat. Der Export schreibt ein kompaktes PDF oder ein geordnetes Bilder-Bundle pro Seite wahlweise in die Dateien-App, iCloud Drive, Google Drive, Dropbox oder ein beliebiges anderes Cloud-Ziel, das Ihr Gerät unterstützt; eine integrierte Konflikt-Erkennung sorgt zusätzlich dafür, dass zwei Scans desselben Dokuments sich nicht gegenseitig überschreiben und kein Inhalt verloren geht. Jeder einzelne Schritt – Aufnahme, Filter, OCR, Zusammenstellung, Export – läuft vollständig lokal, ohne Konto und ohne Upload. Die Benutzeroberfläche ist in 14 Sprachen verfügbar, der Scanner und der PDF-Export sind kostenlos, und Pro ergänzt die App um Cloud-Synchronisation zwischen Geräten, komfortable Stapel-OCR für ganze Ordner und entfernt dauerhaft die Werbung. Paper Scan ist für genau die Momente gemacht, in denen das Papier verschwinden, die zuverlässige digitale Unterlage aber unbedingt bleiben soll.",
    es: "Paper Scan es un escáner de documentos profesional para iPhone que convierte pilas de papel en PDF limpios y con búsqueda de texto, sin enviar ni una sola página a la nube. La ventana de captura usa la lente ultra gran angular para que una página A4 completa quepa sin recortes y sin distortion; seis filtros acelerados por GPU (Magic, Enhanced, Grayscale, B&W, Original y Photo) cubren desde un recibo descolorido hasta una página de revista a color; el OCR en el dispositivo detecta el idioma de origen automáticamente y extrae el texto de cada página, luego lo incorpora al PDF para que cualquier palabra se pueda buscar más tarde en el idioma en que estaba escrita. Los documentos de varias páginas se ensamblan automáticamente, se nombran y se fechan, se guardan en carpetas organizadas, y pueden reordenarse o tener páginas eliminadas antes de exportarlos si una portada extra se coló en el lote. El paso de exportación guarda un PDF o un paquete de imágenes por página en la app Archivos, iCloud Drive, Google Drive, Dropbox o cualquier destino en la nube que admita tu dispositivo, y el flujo de exportación incluye un resolvedor de conflictos para que dos escaneos del mismo documento nunca se sobrescriban entre sí. Cada operación, captura, filtro, OCR, ensamblado y exportación, se ejecuta en local, sin cuenta y sin subidas, lo que resulta ideal para documentos legales, financieros y personales sensibles. La interfaz está disponible en 14 idiomas, el escáner y la exportación a PDF son gratis, y Pro añade sincronización en la nube, OCR por lotes y elimina los anúncios. Paper Scan está pensada para esos momentos en los que necesitas deshacerte del papel y conservar el registro.",
    pt: "O Paper Scan é um scanner de documentos profissional para iPhone que transforma pilhas de papel em PDFs limpos e pesquisáveis, sem enviar uma única página para a nuvem. A janela de captura usa a lente ultra-wide para que uma página A4 inteira caiba de ponta a ponta sem distorção; seis filtros acelerados por GPU — Magic, Enhanced, Grayscale, B&W, Original e Photo — resolvem qualquer situação, desde um recibo desbotado até uma página colorida de revista cheia de imagens. O OCR no próprio aparelho detecta o idioma de origem automaticamente e extrai o texto de cada página, depois indexa dentro do PDF para que qualquer palavra fique pesquisável depois, no idioma em que foi originalmente escrita. Documentos com várias páginas são montados automaticamente, nomeados e datados, salvos em pastas organizadas, e podem ser reordenados ou ter páginas removidas antes da exportação, caso uma capa tenha entrado no lote por engano ou uma página duplicada precise ser excluída. A etapa de exportação grava um PDF ou um pacote de imagens por página no app Arquivos, iCloud Drive, Google Drive, Dropbox ou em qualquer destino na nuvem que o dispositivo aceite, com um resolvedor de conflitos embutido para que dois scans do mesmo documento nunca se sobrescrevam por acidente. Cada operação — captura, filtro, OCR, montagem, exportação — roda localmente, sem conta e sem envio de dados para nenhum servidor. A interface está disponível em 14 idiomas, o scanner e a exportação em PDF são gratuitos, e o Pro adiciona sincronização na nuvem, OCR em lote e remove anúncios. O Paper Scan foi feito para os momentos em que você precisa que o papel suma, mas o registro fique.",
    it: "Paper Scan è uno scanner di documenti professionale per iPhone che trasforma pile di carta in PDF puliti e ricercabili senza mandare una sola pagina sul cloud. La finestra di cattura usa l'obiettivo ultra-grandangolare così una pagina A4 intera ci sta da bordo a bordo senza distorsione; sei filtri accelerati dalla GPU — Magic, Enhanced, Grayscale, B&W, Original e Photo — gestiscono qualsiasi cosa, da una ricevuta sbiadita a una pagina di rivista a colori; l'OCR in locale riconosce automaticamente la lingua di partenza ed estrae il testo da ogni pagina, poi lo indicizza dentro il PDF così qualsiasi parola è ricercabile dopo nella lingua in cui è stata scritta. I documenti multipagina vengono assemblati automaticamente, nominati e datati, salvati in cartelle organizzate, e si possono riordinare o a cui togliere pagine prima dell'esportazione se un foglio di copertina è scivolato nel batch per sbaglio. La fase di esportazione scrive un PDF o un bundle di immagini per pagina nell'app File, iCloud Drive, Google Drive, Dropbox o qualsiasi altra destinazione cloud supportata dal dispositivo, e il flusso include un risolutore di conflitti così due scansioni dello stesso documento non si sovrascrivono mai. Ogni operazione — cattura, filtro, OCR, assemblaggio, esportazione — gira in locale, senza account e senza upload. L'interfaccia è disponibile in quattordici lingue, lo scanner e l'esportazione PDF sono gratuiti, e Pro aggiunge sincronizzazione cloud, OCR in batch e rimuove la pubblicità. Paper Scan è pensato per i momenti in cui la carta deve andare via ma il documento deve restare.",
    ru: "Paper Scan — это профессиональный сканер документов для iPhone, который превращает стопки бумаг в чистые, доступные для поиска PDF без отправки хотя бы одной страницы в облако. Окно захвата использует сверхширокоугольный объектив, так что полная страница A4 помещается от края до края без искажений; шесть фильтров с ускорением на GPU — Magic, Enhanced, Grayscale, B&W, Original и Photo — справляются с задачами от выцветшего чека до цветной страницы журнала; OCR на устройстве автоматически определяет язык источника и извлекает текст с каждой страницы, а затем индексирует его внутри PDF, чтобы любое слово в дальнейшем находилось поиском на языке оригинала. Многостраничные документы собираются автоматически, получают имя и дату, сохраняются в упорядоченные папки, а перед экспортом их можно переупорядочить или удалить отдельные страницы — на случай, если в пакет случайно попал лишний титульный лист. На этапе экспорта PDF или комплект изображений постранично записывается в приложение «Файлы», iCloud Drive, Google Drive, Dropbox или в любую другую облачную цель, которую поддерживает ваше устройство, а в поток экспорта встроен инструмент разрешения конфликтов, чтобы два скана одного документа никогда не затирали друг друга. Каждая операция — захват, фильтр, OCR, сборка, экспорт — выполняется локально, без аккаунта и без загрузки. Интерфейс доступен на 14 языках, сканер и экспорт в PDF бесплатны, а Pro добавляет облачную синхронизацию, пакетный OCR и убирает рекламу. Paper Scan создан для тех моментов, когда бумагу нужно убрать, но запись — сохранить.",
    th: "Paper Scan คือเครื่องสแกนเอกสารระดับมืออาชีพสำหรับ iPhone ที่เปลี่ยนกองกระดาษให้เป็น PDF ที่สะอาดและค้นหาได้ โดยไม่ส่งหน้าเดียวไปยังคลาวด์ หน้าต่างจับภาพใช้เลนส์กว้างพิเศษ ทำให้หน้า A4 เต็มหน้าพอดีโดยไม่มีการบิดเบือน ฟิลเตอร์ที่เร่งด้วย GPU หกแบบ ได้แก่ Magic, Enhanced, Grayscale, B&W, Original และ Photo รองรับทุกอย่างตั้งแต่ใบเสร็จที่ซีดจางไปจนถึงหน้านิตยสารสี OCR บนอุปกรณ์ตรวจจับภาษาต้นฉบับโดยอัตโนมัติและดึงข้อความจากทุกหน้า จากนั้นจัดทำดัชนีภายใน PDF เพื่อให้ค้นหาคำใดก็ได้ในภายหลังในภาษาที่เขียน เอกสารหลายหน้าจะถูกประกอบโดยอัตโนมัติ ตั้งชื่อและระบุวันที่ บันทึกในโฟลเดอร์ที่จัดระเบียบ และสามารถเรียงลำดับใหม่หรือลบหน้าออกก่อนส่งออกได้หากมีหน้าปกหลุดเข้ามาในชุด ขั้นตอนการส่งออกเขียน PDF หรือชุดภาพต่อหน้าลงในแอปไฟล์ iCloud Drive, Google Drive, Dropbox หรือเป้าหมายคลาวด์อื่นๆ ที่อุปกรณ์ของคุณรองรับ และขั้นตอนการส่งออกมีตัวแก้ไขข้อขัดแย้งเพื่อให้การสแกนสองครั้งของเอกสารเดียวกันไม่เขียนทับกัน ทุกการทำงาน จับภาพ ฟิลเตอร์ OCR ประกอบ ส่งออก ทำงานในเครื่อง โดยไม่ต้องสร้างบัญชีและไม่มีการอัปโหลด อินเทอร์เฟซรองรับ 14 ภาษา เครื่องสแกนและการส่งออก PDF ใช้งานได้ฟรี และ Pro เพิ่มการซิงค์คลาวด์ OCR แบบแบตช์ และลบโฆษณา Paper Scan ถูกสร้างมาเพื่อช่วงเวลาที่คุณต้องการกำจัดกระดาษแต่ต้องเก็บบันทึกไว้ค่ะ"
  }
};
